const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',flag:'<path d="M5 21V4m0 0c6-4 8 4 15 0v10c-7 4-9-4-15 0"/>',transactions:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8m-8 4h8m-8 4h5"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>',history:'<path d="M3 10a9 9 0 1 1 1 7M3 4v6h6m3-4v6l4 2"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 3v4l4 2 3-1 3 1 4-2v-4l2-3-2-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3h.01"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2Zm0 6v5m0 3h.01"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',folder:'<path d="M3 7V4h7l3 3h8v13H3Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const fmt=n=>Number(n).toLocaleString('en-US');const dateFmt=v=>new Date(v).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});const timeFmt=v=>new Date(v).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Dubai'})+' GST';
let saved={};
let {transactions,employees}=generateDemo();let rules=Array.isArray(saved.rules)&&saved.rules.length?saved.rules:structuredClone(defaultRules),audit=Array.isArray(saved.audit)?saved.audit:[],reviews=saved.reviews||{},datasetId='demo-v1',batchName='Synthetic HR transactions',lastRun=saved.lastRun||new Date().toISOString(),results,route='overview',page=1,query='',filterSeverity='All',filterProcess='All',filterStatus='All',tab='all',chartMode='rate',drawerReturnFocus=null;
let lastRunId='';
const severityRank={Critical:0,High:1,Medium:2,Low:3};
function persist(){try{localStorage.setItem('aeris-workspace-v1',JSON.stringify({rules,audit:audit.slice(-1000),reviews,lastRun}));return true}catch{toast('Browser storage is full. Export the audit log to preserve your decisions.');return false}}
function log(action,detail,meta={}){audit.push({id:crypto.randomUUID(),timestamp:new Date().toISOString(),actor:'Demo compliance analyst',action,detail,dataset:datasetId,...meta});persist();}
function runChecks(record=true){results=evaluate(transactions,employees,rules);lastRun=new Date().toISOString();lastRunId=crypto.randomUUID();if(record)log('Policy checks completed',`${fmt(transactions.length)} transactions · ${rules.filter(r=>r.active).length} active rules · ${fmt(results.counts.exception)} exceptions · ${fmt(results.counts.unknown)} evidence gaps`,{run_id:lastRunId,counts:results.counts,policy_versions:rules.filter(r=>r.active).map(r=>({id:r.id,version:r.version,text:r.text}))});}
function findingKey(f){const r=rules.find(r=>r.id===f.rule_id);const config=r?JSON.stringify([r.text,r.process,r.kind,r.field,r.value,r.owner,r.severity,r.action]):f.policy;return `${datasetId}:${f.id}:v${f.rule_version}:${config}`}
function findings(){return results.findings.map(f=>({...f,...reviews[findingKey(f)]})).sort((a,b)=>severityRank[a.severity]-severityRank[b.severity]||String(b.date).localeCompare(a.date)||a.id.localeCompare(b.id));}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function badge(v){return `<span class="badge ${esc(v.replaceAll(' ','-'))}">${esc(v==='Review'?'In review':v)}</span>`}
function nav(){const links=[['overview','grid','Overview'],['exceptions','flag','Exceptions'],['transactions','transactions','Transactions'],['policies','book','Policy library'],['insights','spark','Insights'],['audit','history','Audit trail']];$('#nav').innerHTML=links.map(([key,i,label])=>`<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''} title="${label}">${icon(i)}<span class="nav-text">${label}</span>${key==='exceptions'?`<span class="nav-count">${fmt(findings().filter(f=>f.status==='Open').length)}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=[...links,['settings','','Workspace & trust']].find(x=>x[0]===route)?.[2]||'Overview';}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function primary(label,action,i='plus'){return `<button class="btn primary" data-action="${action}">${icon(i)}${label}</button>`}
function secondary(label,action,i='download'){return `<button class="btn" data-action="${action}">${icon(i)}${label}</button>`}
function spark(color){const months=periods().slice(-12),stats=months.map(m=>{const ts=transactions.filter(t=>t.effective_date.startsWith(m)),ids=new Set(ts.map(t=>t.transaction_id)),outcomes=results.outcomes.filter(o=>ids.has(o.transaction_id));if(color==='#b68296')return outcomes.filter(o=>o.status==='exception').length;if(color==='#86a58d')return outcomes.length?100*(1-outcomes.filter(o=>o.status==='unknown').length/outcomes.length):0;return ts.length});const min=Math.min(...stats),max=Math.max(...stats),range=max-min||1;const path=stats.map((n,i)=>`${i?'L':'M'} ${i/Math.max(1,stats.length-1)*69} ${24-(n-min)/range*19}`).join(' ');return `<div class="metric-spark" aria-hidden="true"><svg viewBox="0 0 70 28"><path d="${path}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round"/></svg></div>`;}
function metric(label,value,foot,i,featured=false,sparkColor=''){return `<div class="metric ${featured?'featured':''}"><div class="metric-top">${label}<span class="metric-icon">${icon(i)}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${foot}</div>${sparkColor?spark(sparkColor):''}</div>`}
function periods(){return [...new Set(transactions.map(t=>String(t.effective_date).slice(0,7)))].sort()}
function periodText(){const p=periods();if(p.length===1)return new Date(p[0]+'-15').toLocaleDateString('en-GB',{month:'short',year:'numeric'});return p.length?`${new Date(p[0]+'-15').toLocaleDateString('en-GB',{month:'short',year:'numeric'})} – ${new Date(p.at(-1)+'-15').toLocaleDateString('en-GB',{month:'short',year:'numeric'})}`:'No reporting period'}
function niceCeiling(n){const magnitude=10**Math.floor(Math.log10(Math.max(n,1))),scaled=n/magnitude;return (scaled<=1?1:scaled<=2?2:scaled<=5?5:10)*magnitude;}
function chart(customPoints){const months=periods();if(!months.length)return '<div class="empty">No transactions to chart.</div>';const all=findings().filter(f=>f.evaluation==='exception');const badIds=new Set(all.map(f=>f.transaction_id));const points=months.map(m=>{const ts=transactions.filter(t=>t.effective_date.startsWith(m)),bad=ts.filter(t=>badIds.has(t.transaction_id)).length;return {m,total:ts.length,bad,rate:ts.length?bad/ts.length*100:0}});const shown=(customPoints||points).slice(-24),w=640,h=210,l=36,r=39,top=15,bottom=176,inner=w-l-r,max=Math.max(...shown.map(x=>x.total),1),cap=niceCeiling(max),maxRate=Math.max(10,Math.ceil(Math.max(...shown.map(x=>x.rate))/5)*5),step=inner/shown.length;
 if(!shown.length)return '<div class="empty">No transactions match these filters.</div>';
 let html=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly transaction volume and ${chartMode==='rate'?'exception rate':'number of flagged transactions'}"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b8788c" stop-opacity=".16"/><stop offset="100%" stop-color="#b8788c" stop-opacity="0"/></linearGradient></defs>`;
 for(let i=0;i<5;i++){const y=top+(bottom-top)*i/4;html+=`<line x1="${l}" y1="${y}" x2="${w-r}" y2="${y}" stroke="#edf0f4" stroke-dasharray="3 4"/><text x="${l-8}" y="${y+3}" text-anchor="end">${fmt(cap<10?cap*(1-i/4):Math.round(cap*(1-i/4)))}</text>${chartMode==='rate'?`<text x="${w-r+9}" y="${y+3}">${Math.round(maxRate*(1-i/4))}%</text>`:''}`;}
 const linePoints=shown.map((p,i)=>[l+step*(i+.5),bottom-(bottom-top)*(chartMode==='rate'?p.rate/maxRate:p.bad/cap)]);
 shown.forEach((p,i)=>{const x=l+step*(i+.5),bh=p.total/cap*(bottom-top);html+=`<g class="segment"><title>${esc(new Date(p.m+'-15').toLocaleDateString('en-GB',{month:'long',year:'numeric'}))}: ${fmt(p.total)} transactions, ${fmt(p.bad)} flagged (${p.rate.toFixed(1)}%)</title><rect x="${x-step*.23}" y="${bottom-bh}" width="${step*.46}" height="${bh}" fill="#e2e7ee" rx="3"/><text x="${x}" y="198" text-anchor="middle">${new Date(p.m+'-15').toLocaleDateString('en-GB',{month:'short'})}</text></g>`});
 const path=linePoints.map(([x,y],i)=>`${i?'L':'M'} ${x} ${y}`).join(' ');html+=`<path d="${path} L ${linePoints.at(-1)[0]} ${bottom} L ${linePoints[0][0]} ${bottom} Z" fill="url(#areaFill)"/><path d="${path}" fill="none" stroke="#9d526b" stroke-width="2" stroke-linejoin="round"/>`;
 shown.forEach((p,i)=>{const [x,y]=linePoints[i];html+=`<circle cx="${x}" cy="${y}" r="3" fill="#fff" stroke="#9d526b" stroke-width="1.7"><title>${p.m}: ${p.rate.toFixed(1)}% exception rate · ${p.bad} flagged transactions</title></circle>`});return html+'</svg>';
}
function risk(){const fs=findings().filter(f=>f.evaluation==='exception');const ids=new Set(fs.map(f=>f.transaction_id));const depts=[...new Set(transactions.map(t=>t.department||'Unspecified'))];return depts.map(name=>{const ts=transactions.filter(t=>(t.department||'Unspecified')===name);const n=ts.filter(t=>ids.has(t.transaction_id)).length;return {name,n,total:ts.length,rate:ts.length?n/ts.length*100:0}}).sort((a,b)=>b.rate-a.rate);}
function findingRows(rows,full=false){return rows.map(f=>`<tr class="clickable" tabindex="0" data-finding="${esc(f.id)}" aria-label="Review ${esc(f.title)} for ${esc(f.transaction_id)}"><td><span class="finding-name">${esc(f.title)}</span><span class="subcell">${esc(f.transaction_id)} <span style="margin:0 3px">·</span> ${esc(f.process)}</span></td>${full?`<td><span class="finding-name">${esc(f.employee_name)}</span><span class="subcell">${esc(f.department)}</span></td>`:''}<td>${badge(f.severity)}</td><td><span class="rule-code">${esc(f.rule_id)}</span></td>${full?`<td>${badge(f.status)}</td>`:''}<td><div class="owner-cell"><span class="owner-avatar">${esc(f.owner.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>${esc(f.owner)}</div></td><td class="arrow-cell">${icon('chevron')}</td></tr>`).join('')}
function tableHead(full=false){return `<thead><tr><th>Exception</th>${full?'<th>Employee / team</th>':''}<th>Severity</th><th>Policy</th>${full?'<th>Status</th>':''}<th>Assigned to</th><th></th></tr></thead>`}
function overview(){const fs=findings(),open=fs.filter(f=>!['Resolved','Dismissed'].includes(f.status)),critical=open.filter(f=>f.severity==='Critical').length,applicable=results.counts.pass+results.counts.exception+results.counts.unknown,coverage=applicable?(100*(applicable-results.counts.unknown)/applicable).toFixed(1):'0.0';const riskRows=risk(),maxRisk=Math.max(10,...riskRows.map(r=>r.rate));const prioritized=open.filter(f=>f.evaluation==='exception').slice(0,4);const flaggedTx=new Set(fs.filter(f=>f.evaluation==='exception').map(f=>f.transaction_id)).size;const acts=audit.slice(-3).reverse();
 return heading('YOUR COMPLIANCE COMMAND CENTRE','Clarity in <em>every transaction.</em>','A complete view of HR compliance. Every check, every exception, every next step.',secondary('Export findings','export')+primary('Run a new batch','upload','plus'))+
 `<div class="status-strip"><span>${icon('checkcircle')}<strong>All transactions checked.</strong> ${rules.filter(r=>r.active).length} active policies applied across ${fmt(transactions.length)} transactions.</span><span class="right">Last checked ${timeFmt(lastRun)}</span></div>
 <div class="metrics">${metric('Transactions checked',fmt(transactions.length),`<b>${employees.length?fmt(employees.length):'0'} ${employees.length===1?'employee':'employees'}</b> · full batch coverage`,'transactions',false,'#8d9eab')}${metric('Policy exceptions',fmt(results.counts.exception),`<span class="warm">${fmt(critical)} critical awaiting review</span>`,'flag',true,'#b68296')}${metric('Assessment coverage',`${coverage}<em>%</em>`,`${fmt(results.counts.unknown)} checks need more evidence`,'shield',false,'#86a58d')}${metric('Awaiting a decision',fmt(open.length),`${fmt(fs.filter(f=>f.status==='Resolved').length)} resolved <span style="color:#ccd1d8;margin:0 3px">·</span> Human review required`,'clock')}</div>
 <div class="analytics-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">The compliance picture</h2><p class="panel-subtitle">Transaction volume and policy exceptions over time</p></div><select id="chartMode" class="select-compact" aria-label="Chart metric"><option value="rate" ${chartMode==='rate'?'selected':''}>Exception rate</option><option value="count" ${chartMode==='count'?'selected':''}>Flagged transactions</option></select></div><div class="chart-legend"><span><i class="legend-fill"></i>Transactions · left axis</span><span><i class="legend-line"></i>${chartMode==='rate'?'Exception rate · right axis':'Flagged transactions · left axis'}</span><span style="margin-left:auto">${periodText()}</span></div><div class="chart-wrap">${chart()}</div><div class="chart-note">${icon('info')}<span><strong>${fmt(flaggedTx)} ${flaggedTx===1?'transaction':'transactions'}</strong> ${flaggedTx===1?'contains':'contain'} a policy exception. One transaction may have several findings.</span></div></section>
 <section class="panel"><div class="panel-header"><div><h2 class="panel-title">Where attention is needed</h2><p class="panel-subtitle">Flagged transactions as a share of each team's volume</p></div><span style="color:#a9afb9">${icon('flag')}</span></div><div class="risk-content">${riskRows.slice(0,5).map((r,i)=>`<div class="risk-row"><div class="risk-line"><span>${esc(r.name)}</span><span class="risk-value"><small>${r.n} / ${fmt(r.total)}</small>${r.rate.toFixed(1)}%</span></div><div class="track"><i style="width:${Math.max(1,r.rate/maxRisk*100)}%;opacity:${1-i*.14}"></i></div></div>`).join('')}</div><div class="panel-footer"><span>Normalised by transaction volume</span><a href="#transactions" class="btn link">Explore teams ${icon('arrow')}</a></div></section></div>
 <div class="lower-grid"><section class="panel table-panel"><div class="panel-header"><div style="display:flex;align-items:center"><h2 class="panel-title">Your priority queue</h2><span class="counter">${fmt(open.filter(f=>f.evaluation==='exception').length)}</span></div><a href="#exceptions" class="btn link">View all exceptions ${icon('arrow')}</a></div><div class="table-wrap"><table>${tableHead()}<tbody>${prioritized.length?findingRows(prioritized):'<tr><td colspan="5"><div class="empty">No policy exceptions await review.</div></td></tr>'}</tbody></table></div><div class="queue-footer"><span>Prioritised by severity, then earliest due date</span><span style="display:flex;gap:5px;align-items:center">${icon('shield')}Your review makes the difference</span></div></section>
 <section class="panel"><div class="panel-header"><h2 class="panel-title">A trail of accountability</h2><span style="color:#a8b0bb">${icon('history')}</span></div><div class="activity-list">${acts.map(a=>`<div class="activity-item"><span class="activity-icon">${icon(a.action.includes('checks')?'check':a.action.includes('policy')?'book':'history')}</span><div class="activity-copy"><strong>${esc(a.action)}</strong><p>${esc(a.detail.length>90?a.detail.slice(0,90)+'…':a.detail)}</p><small>${timeFmt(a.timestamp)}</small></div></div>`).join('')}</div><div class="panel-footer"><span>Every action leaves a record</span><a href="#audit" class="btn link">View trail ${icon('arrow')}</a></div></section></div>`;
}
function searchBox(placeholder){return `<div class="search">${icon('search')}<input id="searchInput" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}"></div>`}
const select=(id,label,options,value)=>`<select id="${id}" aria-label="${label}">${options.map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;
function exceptionFiltered(){return findings().filter(f=>(tab==='all'||tab==='gaps'&&f.evaluation==='unknown'||tab==='policy'&&f.evaluation==='exception')&&(filterSeverity==='All severities'||filterSeverity==='All'||f.severity===filterSeverity)&&(filterStatus==='All statuses'||filterStatus==='All'||f.status===filterStatus)&&(filterProcess==='All processes'||filterProcess==='All'||f.process===filterProcess)&&`${f.title} ${f.transaction_id} ${f.employee_name} ${f.department} ${f.rule_id} ${f.owner}`.toLowerCase().includes(query.toLowerCase()));}
function pagination(total,size=12){const max=Math.max(1,Math.ceil(total/size));page=Math.min(page,max);return `<div class="queue-footer"><span>${total?`${(page-1)*size+1}–${Math.min(page*size,total)}`:'0'} of ${fmt(total)} records</span><div class="pagination"><button data-page="${page-1}" ${page<=1?'disabled':''} aria-label="Previous page">‹</button><span>Page ${page} of ${max}</span><button data-page="${page+1}" ${page>=max?'disabled':''} aria-label="Next page">›</button></div></div>`;}
function exceptions(){const fs=exceptionFiltered(),foot=pagination(fs.length);return heading('EXPLAIN. ASSIGN. RESOLVE.','Every exception. <em>A clear next step.</em>','Evidence you can understand. Ownership you can act on.',secondary('Export findings','export')+primary('Run checks','rerun','refresh'))+`<div class="tabs"><button class="tab ${tab==='all'?'active':''}" data-tab="all">All findings <small>${fmt(results.findings.length)}</small></button><button class="tab ${tab==='policy'?'active':''}" data-tab="policy">Policy exceptions <small>${fmt(results.counts.exception)}</small></button><button class="tab ${tab==='gaps'?'active':''}" data-tab="gaps">Evidence gaps <small>${fmt(results.counts.unknown)}</small></button></div><div class="toolbar">${searchBox('Search findings, employees, policies…')}${select('severityFilter','Filter severity',['All severities','Critical','High','Medium','Low'],filterSeverity)}${select('processFilter','Filter process',['All processes',...processes],filterProcess)}${select('statusFilter','Filter status',['All statuses','Open','Review','Resolved','Dismissed'],filterStatus)}<span class="results-label">${fmt(fs.length)} findings</span></div><section class="panel"><div class="table-wrap"><table>${tableHead(true)}<tbody>${fs.length?findingRows(fs.slice((page-1)*12,page*12),true):'<tr><td colspan="7"><div class="empty"><strong>No matching findings.</strong>Try a different filter or search term.</div></td></tr>'}</tbody></table></div>${foot}</section>`}
function txFiltered(){return transactions.filter(t=>(filterProcess==='All'||filterProcess==='All processes'||t.type===filterProcess)&&`${t.transaction_id} ${t.employee_id} ${t.department} ${t.type}`.toLowerCase().includes(query.toLowerCase()));}
function transactionPage(){const ts=txFiltered(),foot=pagination(ts.length,15);const ids=new Set(findings().filter(f=>f.evaluation==='exception').map(f=>f.transaction_id)),unknown=new Set(findings().filter(f=>f.evaluation==='unknown').map(f=>f.transaction_id));return heading('COMPLETE TRANSACTION COVERAGE','Every record. <em>Accounted for.</em>','Explore the supplied batch and the outcome of its applicable policy checks.',secondary('Download demo files','samples')+primary('Import a batch','upload','upload'))+`<div class="info-banner">${icon('folder')}<span><strong>${esc(batchName)}</strong> · ${fmt(transactions.length)} transactions · ${fmt(employees.length)} employee records · ${periodText()}${datasetId!=='demo-v1'?'<br>Imported records are held in this tab only. Reloading restores the demo batch.':''}</span></div><div class="toolbar">${searchBox('Search transaction, employee or team…')}${select('processFilter','Filter process',['All processes',...processes],filterProcess)}<span class="results-label">${fmt(ts.length)} transactions</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Employee</th><th>Team</th><th>Amount</th><th>Effective date</th><th>Outcome</th><th></th></tr></thead><tbody>${ts.slice((page-1)*15,page*15).map(t=>`<tr class="clickable" tabindex="0" data-transaction="${esc(t.transaction_id)}" aria-label="Open transaction ${esc(t.transaction_id)}"><td><span class="finding-name">${esc(t.transaction_id)}</span><span class="subcell">${esc(t.type)}</span></td><td>${esc(t.employee_id)}</td><td>${esc(t.department||'Unspecified')}</td><td>${Number.isFinite(Number(t.amount))?'AED '+fmt(t.amount):'Not supplied'}</td><td>${dateFmt(t.effective_date)}</td><td>${ids.has(t.transaction_id)?badge('High').replace('High</span>','Exception</span>'):unknown.has(t.transaction_id)?badge('unknown').replace('unknown</span>','Evidence gap</span>'):badge('pass').replace('pass</span>','Passed</span>')}</td><td>${icon('chevron')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No matching transactions.</div></td></tr>'}</tbody></table></div>${foot}</section>`}
function policyPage(){const rs=rules.filter(r=>`${r.id} ${r.title} ${r.text}`.toLowerCase().includes(query.toLowerCase()));return heading('CONSISTENCY, WRITTEN INTO EVERY CHECK','Clear policies. <em>Consistent decisions.</em>','Versioned, traceable rules that turn written policy into repeatable checks.',secondary('Export policies','policy-export')+primary('Create a rule','new-rule'))+`<div class="info-banner">${icon('info')}<span><strong>Illustrative policies, ready to be replaced.</strong> These ${defaultRules.length} example policies demonstrate the engine. They are not Emirates policies. Import the official policy configuration when available.</span></div><div class="toolbar">${searchBox('Search policy name, wording or ID…')}<span class="results-label">${rules.filter(r=>r.active).length} active · ${rules.length} total rules</span></div><div class="rule-grid">${rs.map(r=>`<article class="panel rule-card"><div class="rule-head"><span class="rule-code">${esc(r.id)} <span style="color:#b4bbc5">/ v${r.version}</span></span>${badge(r.severity)}</div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="rule-status">${icon('folder')} ${esc(r.process==='All'?'All HR processes':r.process)} <span style="margin-left:auto">${fmt(results.findings.filter(f=>f.rule_id===r.id&&f.evaluation==='exception').length)} exceptions</span></div><div class="rule-card-bottom"><span>${esc(r.owner)}</span><button class="${r.active?'':'paused'}" data-rule-toggle="${esc(r.id)}" aria-label="${r.active?'Pause':'Activate'} ${esc(r.title)}">${r.active?'● Active':'○ Paused'}</button></div></article>`).join('')||'<div class="empty">No policies match your search.</div>'}</div>`}
let trendProcess='All',trendTeam='All',trendRule='All';
function trendPanel(){const pts=monthlyTrends(transactions,results.outcomes,{process:trendProcess,team:trendTeam,rule:trendRule},employees),total=pts.reduce((n,p)=>n+p.total,0),bad=pts.reduce((n,p)=>n+p.bad,0),gaps=pts.reduce((n,p)=>n+p.unknown,0);return `<section class="panel" style="margin-bottom:22px"><div class="panel-header"><div><h2 class="panel-title">Monthly trends by process, team and policy</h2><p class="panel-subtitle">Combine filters to compare the relevant transaction volume and exception rate.</p></div></div><div class="toolbar" style="padding:18px 20px 0">${select('trendProcess','Trend process',['All',...processes],trendProcess)}${select('trendTeam','Trend team',['All',...[...new Set(transactions.map(t=>t.department||employees.find(e=>e.employee_id===t.employee_id)?.department||'Unspecified'))].sort()],trendTeam)}<select id="trendRule" aria-label="Trend policy"><option value="All">All policies</option>${rules.filter(r=>r.active).map(r=>`<option value="${esc(r.id)}" ${r.id===trendRule?'selected':''}>${esc(r.id+' · '+r.title)}</option>`).join('')}</select></div><div class="chart-legend"><span><i class="legend-fill"></i>Relevant transactions · left axis</span><span><i class="legend-line"></i>Exception rate · right axis</span></div><div class="chart-wrap">${chart(pts)}</div><div class="chart-note" id="trendSummary">${fmt(bad)} flagged of ${fmt(total)} relevant transactions (${total?(100*bad/total).toFixed(2):'0.00'}%). ${fmt(gaps)} transaction(s) have missing evidence. ${trendRule==='All'?'A transaction is counted once even with multiple exceptions.':'Only transactions with an applicable check for this policy enter the denominator.'} Missing evidence is not counted as a violation.</div></section>`;}
function insightsPage(){
 const fs=findings().filter(f=>f.evaluation==='exception'),badIds=new Set(fs.map(f=>f.transaction_id));
 const processStats=processes.map(name=>{const ts=transactions.filter(t=>t.type===name),n=ts.filter(t=>badIds.has(t.transaction_id)).length;return {name,total:ts.length,n,rate:ts.length?n/ts.length*100:0}}).sort((a,b)=>b.rate-a.rate);
 const maxRate=Math.max(10,...processStats.map(p=>p.rate));const ruleStats=rules.filter(r=>r.active).map(r=>{const applicable=results.outcomes.filter(o=>o.rule_id===r.id),exceptions=applicable.filter(o=>o.status==='exception').length,gaps=applicable.filter(o=>o.status==='unknown').length;return {...r,total:applicable.length,exceptions,gaps,rate:applicable.length?exceptions/applicable.length*100:0}}).sort((a,b)=>b.exceptions-a.exceptions);
 return heading('FROM INDIVIDUAL FINDINGS TO SYSTEMIC IMPROVEMENT','See the pattern. <em>Improve the process.</em>','Explore policy and process hotspots with the transaction volume behind every rate.',secondary('Export findings','export'))+trendPanel()+`<div class="analytics-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Exceptions by HR process</h2><p class="panel-subtitle">Share of transactions with at least one confirmed policy exception</p></div></div><div class="risk-content" style="display:block">${processStats.map((p,i)=>`<div class="risk-row"><div class="risk-line"><span>${esc(p.name)}</span><span class="risk-value"><small>${p.n} of ${fmt(p.total)} transactions</small>${p.rate.toFixed(1)}%</span></div><div class="track"><i style="width:${Math.max(1,p.rate/maxRate*100)}%;opacity:${1-i*.1}"></i></div></div>`).join('')}</div><div class="chart-note">${icon('info')}Evidence gaps are excluded from confirmed policy exceptions.</div></section><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Team hotspots</h2><p class="panel-subtitle">Normalised by each team's transaction volume</p></div></div><div class="risk-content" style="display:block">${risk().map((p,i)=>`<div class="risk-row"><div class="risk-line"><span>${esc(p.name)}</span><span class="risk-value"><small>${p.n} of ${fmt(p.total)}</small>${p.rate.toFixed(1)}%</span></div><div class="track"><i style="width:${Math.max(1,p.rate/Math.max(10,...risk().map(x=>x.rate))*100)}%;opacity:${1-i*.1}"></i></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-header" style="padding-bottom:18px"><div><h2 class="panel-title">Policies driving exceptions</h2><p class="panel-subtitle">Exception rate uses applicable checks as its denominator. Missing evidence is reported separately.</p></div></div><div class="table-wrap"><table><thead><tr><th>Policy</th><th>Process</th><th>Applicable checks</th><th>Exceptions</th><th>Exception rate</th><th>Evidence gaps</th></tr></thead><tbody>${ruleStats.map(r=>`<tr><td><span class="finding-name">${esc(r.title)}</span><span class="subcell">${esc(r.id)} · v${r.version}</span></td><td>${esc(r.process)}</td><td>${fmt(r.total)}</td><td><strong style="color:${r.exceptions?'var(--red)':'#9aa4b2'}">${fmt(r.exceptions)}</strong></td><td>${r.rate.toFixed(2)}%</td><td>${fmt(r.gaps)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function auditPage(){const rows=audit.filter(a=>`${a.action} ${a.detail} ${a.actor}`.toLowerCase().includes(query.toLowerCase())).reverse(),foot=pagination(rows.length,15);return heading('THE EVIDENCE BEHIND EVERY DECISION','Accountability, <em>by design.</em>','Follow check runs, policy changes, assignments and human decisions.',secondary('Export audit evidence','audit-export'))+`<div class="info-banner">${icon('lock')}<span><strong>Prototype audit trail.</strong> Decisions are saved in this browser. This is a reviewable activity record; an enterprise pilot needs authenticated identities and tamper-resistant server storage.</span></div><div class="toolbar">${searchBox('Search actions or decisions…')}<span class="results-label">${fmt(rows.length)} recorded events</span></div><section class="panel"><div class="table-wrap"><table class="audit-table"><thead><tr><th>Time · Dubai</th><th>Action</th><th>Details</th><th>Actor</th></tr></thead><tbody>${rows.slice((page-1)*15,page*15).map(a=>`<tr><td style="white-space:nowrap">${timeFmt(a.timestamp)}</td><td><span class="finding-name">${esc(a.action)}</span></td><td>${esc(a.detail)}${a.note?`<span class="subcell">Reason: ${esc(a.note)}</span>`:''}</td><td>${esc(a.actor)}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">No matching events.</div></td></tr>'}</tbody></table></div>${foot}</section>`}
function settingsPage(){return heading('A RESPONSIBLE FOUNDATION','Trust is part <em>of the workflow.</em>','A transparent prototype built around evidence, privacy and human judgment.')+`<div class="trust-grid"><section class="panel trust-card"><div class="eyebrow">${icon('shield')} HUMAN OVERSIGHT</div><h3>The tool recommends. A person decides.</h3><p>Checks flag policy exceptions and evidence gaps. Reviewers can assign an owner, request review, resolve or dismiss a finding with a recorded reason. No employee transaction is changed automatically.</p><ul><li>Evidence and policy wording accompany every finding.</li><li>Missing evidence is separate from a confirmed violation.</li><li>Neutral explanations describe records, never blame employees.</li><li>Review notes can record employee context or a correction request.</li></ul></section><section class="panel trust-card"><div class="eyebrow">${icon('lock')} DATA HANDLING</div><h3>Your files stay in this browser tab.</h3><p>All checks run on your device. Uploaded CSVs are not sent to a model or application server. Import only synthetic data. Imported records stay in memory; refreshing restores the demo dataset.</p><p>Rule configurations and review activity are stored in this browser. Export audit evidence before clearing browser data. This prototype has no application-level role enforcement or authenticated reviewer identity.</p></section><section class="panel trust-card"><div class="eyebrow">${icon('book')} POLICY GOVERNANCE</div><h3>Transparent, approved rule logic.</h3><p>The initial library contains illustrative policies. A guided editor lets an analyst define a condition, inspect its wording and preview its impact before approving activation. Rule execution is deterministic; no generative model is connected.</p><p>Arbitrary written policy still needs a human to translate and validate it. The rule builder supports explicit comparison, approval, document, date and employee-reference checks.</p>${secondary('Download policy configuration','policy-export')}</section><section class="panel trust-card"><div class="eyebrow">${icon('folder')} PILOT PATH</div><h3>Designed to move inside Emirates.</h3><p>The static interface and checking engine can be hosted internally. A pilot would add enterprise sign-in, role permissions, a controlled transaction source, a scheduled worker, an approved policy workflow, and append-only audit storage.</p><p>Detection uses executable policy logic. A future AI assistant could draft rules or explain grounded evidence within an approved private deployment, subject to human approval.</p>${secondary('Download demo files','samples')}</section><section class="panel trust-card"><div class="eyebrow">${icon('refresh')} DEMO WORKSPACE</div><h3>Start again with a clean example.</h3><p>Reset restores the 16 example policies, 10,000 generated transactions and 2,000 synthetic employees. It clears this prototype's locally saved reviews and audit history.</p><button class="btn" data-action="reset">Reset demo workspace</button></section><section class="panel trust-card"><div class="eyebrow">${icon('download')} SUBMISSION READINESS</div><h3>Ready for the official pack.</h3><p>Use the import screen to inspect required CSV fields. The current finding export uses the prototype schema. The competition's exact finding format, real policy text, planted answer key and hidden test file have not been supplied.</p><p>Official-format mapping and detection validation against the competition pack are the next integration steps.</p>${secondary('Export current findings','export')}</section></div>`}
function render(){nav();const renders={overview,exceptions,transactions:transactionPage,policies:policyPage,insights:insightsPage,audit:auditPage,settings:settingsPage};$('#main').innerHTML=(renders[route]||overview)();bindMain();hydrateIcons();}
function hydrateIcons(){$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function bindMain(){$$('[data-action]',$('#main')).forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-finding]').forEach(r=>{r.onclick=()=>openFinding(r.dataset.finding);r.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();r.click()}}});$$('[data-transaction]').forEach(r=>{r.onclick=()=>openTransaction(r.dataset.transaction);r.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();r.click()}}});$$('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;page=1;render()});$$('[data-rule-toggle]').forEach(b=>b.onclick=()=>toggleRule(b.dataset.ruleToggle));const search=$('#searchInput');if(search)search.oninput=()=>{query=search.value;page=1;const pos=search.selectionStart;render();$('#searchInput').focus();$('#searchInput').setSelectionRange(pos,pos)};for(const [id,assign]of [['severityFilter',v=>filterSeverity=v],['processFilter',v=>filterProcess=v],['statusFilter',v=>filterStatus=v]]){const s=$('#'+id);if(s)s.onchange=()=>{assign(s.value);page=1;render()}}if($('#chartMode'))$('#chartMode').onchange=e=>{chartMode=e.target.value;render()};}
function navigate(){const next=location.hash.slice(1)||'overview';if(next!==route){route=next;page=1;query='';filterSeverity=filterProcess=filterStatus='All';tab='all'}render()};window.addEventListener('hashchange',navigate);
function drawer(title,content,eyebrow='FINDING DETAILS'){drawerReturnFocus=document.activeElement;$('#drawer').innerHTML=`<div class="drawer-header"><div><div class="eyebrow">${eyebrow}</div><h2 id="drawerTitle">${title}</h2></div><button class="icon-button" id="closeDrawer" aria-label="Close details">${icon('close')}</button></div>${content}`;$('#overlay').hidden=false;$('#drawer').hidden=false;document.body.style.overflow='hidden';$('#closeDrawer').onclick=closeDrawer;$('#closeDrawer').focus();}
function closeDrawer(){$('#drawer').hidden=true;$('#overlay').hidden=true;document.body.style.overflow='';drawerReturnFocus?.isConnected&&drawerReturnFocus.focus();}
$('#overlay').onclick=closeDrawer;
function openFinding(id){const f=findings().find(x=>x.id===id);if(!f)return;const history=audit.filter(a=>a.finding_id===id&&a.dataset===datasetId&&a.rule_version===f.rule_version&&a.policy===f.policy).reverse();drawer(esc(f.title),`<div class="drawer-tags">${badge(f.severity)}${badge(f.status)}${f.evaluation==='unknown'?badge('unknown').replace('unknown</span>','Evidence gap</span>'):''}<span class="rule-code" style="margin-left:auto">${esc(f.rule_id)} · v${f.rule_version}</span></div><div class="explanation-box">${esc(f.explanation)}</div><div class="meta-grid"><div><small>TRANSACTION</small><strong>${esc(f.transaction_id)}</strong></div><div><small>EMPLOYEE · SYNTHETIC</small><strong>${esc(f.employee_name)} · ${esc(f.employee_id)}</strong></div><div><small>PROCESS / TEAM</small><strong>${esc(f.process)} · ${esc(f.department)}</strong></div><div><small>EFFECTIVE DATE</small><strong>${dateFmt(f.date)}</strong></div></div><section class="detail-section"><h3>The policy behind this check</h3><p>${esc(f.policy)}</p><span class="subcell">Approved rule ${esc(f.rule_id)} · version ${f.rule_version} · ${esc(rules.find(r=>r.id===f.rule_id)?.source||'Human-configured rule')}</span></section><section class="detail-section"><h3>Evidence from the record</h3><table class="evidence"><tbody>${f.evidence.map(e=>`<tr><td>${esc(e.field)}</td><td>${esc(e.value)}</td></tr>`).join('')}</tbody></table></section><section class="detail-section"><h3>Suggested next step</h3><p>${esc(f.action)}</p></section><section class="detail-section"><h3>Your review decision</h3><form id="reviewForm"><div class="form-row"><div class="form-field"><label for="reviewOwner">Assigned owner</label><select id="reviewOwner">${[...new Set([...owners,f.owner])].map(o=>`<option ${o===f.owner?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div class="form-field"><label for="reviewStatus">Status</label><select id="reviewStatus">${['Open','Review','Resolved','Dismissed'].map(s=>`<option value="${s}" ${s===f.status?'selected':''}>${s==='Review'?'In review':s}</option>`).join('')}</select></div></div><div class="form-field"><label for="reviewNote">Review note / employee context</label><textarea id="reviewNote" required placeholder="Record the reason for your decision, supporting evidence, or information to request."></textarea><small>Required for every saved decision. No transaction is changed.</small></div><div id="reviewError"></div><div class="drawer-actions"><button type="submit" class="btn primary">${icon('check')}Save human decision</button><button type="button" class="btn" id="viewTransaction">View transaction</button></div></form></section><section class="detail-section"><h3>Finding history</h3>${history.map(h=>`<div class="history-item"><strong>${esc(h.action)}</strong> · ${esc(h.detail)}${h.note?`<div>${esc(h.note)}</div>`:''}<small>${timeFmt(h.timestamp)} · ${esc(h.actor)}</small></div>`).join('')||'<p>No review decisions recorded yet.</p>'}</section>`);$('#viewTransaction').onclick=()=>openTransaction(f.transaction_id);$('#reviewForm').onsubmit=e=>{e.preventDefault();const note=$('#reviewNote').value.trim();if(!note){$('#reviewError').innerHTML='<div class="inline-error">Please record a reason for this decision.</div>';return;}const owner=$('#reviewOwner').value,status=$('#reviewStatus').value;reviews[findingKey(f)]={owner,status,reviewed_at:new Date().toISOString()};log('Human review saved',`${f.transaction_id} · ${f.rule_id}: ${f.status} → ${status}; owner: ${owner}`,{finding_id:f.id,note,previous_status:f.status,status,owner,rule_id:f.rule_id,rule_version:f.rule_version,policy:f.policy,evidence:f.evidence});closeDrawer();render();toast('Decision saved. The transaction has not been changed.');};}
function openTransaction(id){const t=transactions.find(t=>t.transaction_id===id),fs=findings().filter(f=>f.transaction_id===id),checks=results.outcomes.filter(o=>o.transaction_id===id);if(!t)return;drawer(esc(id),`<div class="drawer-tags"><span class="rule-code">${esc(t.type)}</span><span class="subcell">${checks.length} applicable checks · ${fs.length} findings</span></div><section class="detail-section"><h3>Transaction record</h3><table class="evidence"><tbody>${Object.entries(t).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)||'Not supplied'}</td></tr>`).join('')}</tbody></table></section><section class="detail-section"><h3>Policy check outcomes</h3>${checks.map(c=>`<div class="history-item" style="display:flex;justify-content:space-between;gap:10px"><span><strong>${esc(c.rule_id)}</strong> · ${esc(rules.find(r=>r.id===c.rule_id)?.title)}</span>${badge(c.status==='exception'?'High':c.status).replace('High</span>','Exception</span>')}</div>`).join('')}</section><section class="detail-section"><h3>Related findings</h3>${fs.length?fs.map(f=>`<button class="btn" data-related="${esc(f.id)}" style="display:flex;justify-content:space-between;width:100%;margin-bottom:8px;white-space:normal;text-align:left">${esc(f.title)} ${icon('arrow')}</button>`).join(''):'<p>All applicable checks passed.</p>'}</section>`,'TRANSACTION EVIDENCE');$$('[data-related]').forEach(b=>b.onclick=()=>openFinding(b.dataset.related));}
function exportFindings(){const fs=route==='exceptions'?exceptionFiltered():findings();download('aeris-findings.csv',findingsCSV(fs,lastRun,datasetId),'text/csv;charset=utf-8');log('Findings exported',`${fmt(fs.length)} findings exported using the prototype CSV schema.`);toast(`${fmt(fs.length)} findings exported. Official submission mapping is pending.`);}
function policyMarkdown(){return '# Aeris · Illustrative policy configuration\n\nThese example policies are not Emirates policies. Human-approved structured checks follow.\n\n'+rules.map(r=>`## ${r.id}: ${r.title}\n${r.text}\n`).join('\n')+'\n## Executable configuration\n\n```json\n'+JSON.stringify(rules,null,2)+'\n```\n';}
function showSamples(){drawer('A safe place to start.',`<p class="subtitle">Generated example data only. Download the files to explore the schema or try the import workflow.</p><div class="detail-section"><h3>Available files</h3><div class="form-field"><button class="btn" id="sampleTransactions">${icon('download')}transactions.csv · 10,000 records</button><button class="btn" id="sampleEmployees">${icon('download')}employees.csv · 2,000 records</button><button class="btn" id="sampleRules">${icon('download')}policy_rules.md · structured example policies</button><button class="btn" id="sampleFinding">${icon('download')}finding_format.csv · prototype format</button></div></div><div class="info-banner">${icon('info')}<span>These are generated demonstration files. The official competition data, policies and output schema have not been supplied.</span></div>`,'SYNTHETIC DATA PACK');$('#sampleTransactions').onclick=()=>download('transactions.csv',toCSV(generateDemo().transactions),'text/csv');$('#sampleEmployees').onclick=()=>download('employees.csv',toCSV(generateDemo().employees),'text/csv');$('#sampleRules').onclick=()=>download('policy_rules.md',policyMarkdown(),'text/markdown');$('#sampleFinding').onclick=()=>download('finding_format.csv',findingsCSV(findings().slice(0,5),lastRun,datasetId),'text/csv');}

function openUpload(){drawer('A new batch. A complete check.',`<p class="subtitle">Import synthetic transaction and employee files. Processing happens in this browser tab.</p><form id="uploadForm"><div class="upload-zone">${icon('upload')}<h3>Start with your transaction file</h3><p>CSV · up to 15 MB · synthetic data only</p><input id="txFile" type="file" accept=".csv,text/csv" required aria-label="Transaction CSV"></div><div class="form-field"><label for="employeeFile">Employee register · CSV</label><input id="employeeFile" type="file" accept=".csv,text/csv" required><small>Both files are required to avoid joining new transactions to the demo register.</small></div><div class="form-field"><label for="policyFile">Policy configuration · optional JSON or Markdown</label><input id="policyFile" type="file" accept=".json,.md"><small>Upload a JSON rule array or Markdown containing one fenced JSON rule array. Plain prose must be translated through the guided rule editor before execution. Without a file, the current policies are used.</small></div><div class="form-field"><label style="display:flex;align-items:flex-start;gap:8px;font-weight:400;line-height:1.7"><input id="syntheticConsent" type="checkbox" required style="width:auto;margin-top:3px">I confirm these files contain synthetic data and have reviewed the policies to apply.</label></div><div id="uploadError"></div><div class="drawer-actions"><button class="btn primary" type="submit">${icon('shield')}Validate & run checks</button><button class="btn" type="button" id="getSample">Download example files</button></div></form><section class="detail-section"><h3>Expected fields</h3><p><strong>Transactions:</strong> transaction_id, employee_id, type, effective_date. Rule evidence uses amount, grade, department, requester, approver, approver_role, submitted_at, approved_at, documents.</p><p><strong>Employees:</strong> employee_id; optionally name, grade, department, location, manager and hire_date.</p><p>Dates use YYYY-MM-DD or ISO timestamps. Documents use semicolon-separated names. Types: ${processes.join(', ')}. Unknown identifiers, malformed files and duplicates are surfaced before running.</p></section>`,'BATCH IMPORT');$('#getSample').onclick=showSamples;$('#uploadForm').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',$('#uploadForm'));b.disabled=true;b.textContent='Validating files…';try{const txf=$('#txFile').files[0],emf=$('#employeeFile').files[0],pf=$('#policyFile').files[0];for(const file of [txf,emf,pf].filter(Boolean))if(file.size>15*1024*1024)throw Error(`${file.name} exceeds 15 MB.`);const txText=await txf.text(),emText=await emf.text();const newTx=validateRows(parseCSV(txText),'transactions'),newEm=validateRows(parseCSV(emText),'employees');if(newTx.length>100000)throw Error('This browser prototype supports up to 100,000 transactions per batch.');let newRules=rules;if(pf){const raw=await pf.text(),json=pf.name.endsWith('.md')?raw.match(/```json\s*([\s\S]*?)```/i)?.[1]:raw;if(!json)throw Error('Markdown needs a fenced JSON rule array. Use the rule editor to translate prose first.');const parsed=JSON.parse(json);if(!Array.isArray(parsed)||!parsed.length||parsed.length>100)throw Error('Provide an array of 1–100 structured policy rules.');const ids=new Set();newRules=parsed.map((r,i)=>{if(!r.id||ids.has(r.id))throw Error('Each imported policy needs a unique rule ID.');ids.add(r.id);return validateRule({...r,version:Number.isInteger(r.version)&&r.version>0?r.version:1,active:r.active!==false,source:'Imported structured policy configuration'});});if(!newRules.some(r=>r.active))throw Error('Activate at least one policy before running a batch.');}
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(txText+'\n'+emText));const newId='batch-'+[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');transactions=newTx;employees=newEm;rules=newRules;datasetId=newId;batchName=txf.name;log('Synthetic batch imported',`${txf.name} · ${fmt(newTx.length)} transactions · ${fmt(newEm.length)} ${newEm.length===1?'employee':'employees'}`);runChecks();closeDrawer();location.hash='overview';render();toast(`Checked all ${fmt(newTx.length)} transactions. Review the findings.`);}catch(err){$('#uploadError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`;}finally{b.disabled=false;b.innerHTML=icon('shield')+'Validate & run checks';}};}
const fields=['amount','grade','approver','requester','submitted_at','approved_at','effective_date','documents','employee_id'];
function ruleDraft(){return {id:'POL-'+String(Math.max(0,...rules.map(r=>Number(r.id.replace('POL-',''))||0))+1).padStart(3,'0'),title:$('#ruleTitle').value.trim(),text:$('#ruleText').value.trim(),process:$('#ruleProcess').value,kind:$('#ruleKind').value,field:$('#ruleField').value,value:$('#ruleValue').value.trim(),severity:$('#ruleSeverity').value,owner:$('#ruleOwner').value,action:$('#ruleAction').value.trim(),version:1,active:true,source:'Human-approved rule builder'};}
function openRuleBuilder(){drawer('Turn policy into a clear check.',`<p class="subtitle">Define a rule, preview its effect on the current batch, then approve activation.</p><form id="ruleForm"><div class="form-field"><label for="ruleTitle">Policy title</label><input id="ruleTitle" required placeholder="e.g. Maximum allowance amount"></div><div class="form-field"><label for="ruleText">Written policy</label><textarea id="ruleText" required placeholder="Describe the exact policy requirement."></textarea><small>Policy text is retained as evidence. Configure its precise executable condition below.</small></div><div class="form-row"><div class="form-field"><label for="ruleProcess">Applies to</label><select id="ruleProcess">${['All',...processes].map(p=>`<option>${p}</option>`).join('')}</select></div><div class="form-field"><label for="ruleSeverity">Severity</label><select id="ruleSeverity">${['Critical','High','Medium','Low'].map(p=>`<option ${p==='Medium'?'selected':''}>${p}</option>`).join('')}</select></div></div><div class="form-field"><label for="ruleKind">Condition</label><select id="ruleKind"><option value="maximum">Value must not exceed a limit</option><option value="minimum">Value must meet a minimum</option><option value="different">Two fields must be different</option><option value="before">First date must be on/before second</option><option value="document">A named document is required</option><option value="approval">Above threshold, require HR director approval</option><option value="employee">Employee must exist in register</option></select></div><div class="form-row"><div class="form-field"><label for="ruleField">Record field</label><select id="ruleField">${fields.map(f=>`<option>${f}</option>`).join('')}</select></div><div class="form-field" id="valueField"><label for="ruleValue">Limit, other field or document</label><input id="ruleValue" required placeholder="e.g. 15000"><small id="valueHint">A numeric maximum, such as 15000.</small></div></div><div class="form-field"><label for="ruleOwner">Responsible owner</label><select id="ruleOwner">${owners.map(o=>`<option>${o}</option>`).join('')}</select></div><div class="form-field"><label for="ruleAction">Suggested corrective action</label><textarea id="ruleAction" required placeholder="What should the assigned owner do next?"></textarea></div><div id="ruleError"></div><div id="rulePreview"></div><div class="drawer-actions"><button class="btn" type="button" id="previewRule">${icon('search')}Preview impact</button><button class="btn primary" id="activateRule" type="submit" disabled>${icon('check')}Approve & activate</button></div><p class="subtitle">Activation is a human policy decision. Preview again after changing the rule.</p></form>`,'GUIDED POLICY BUILDER');let previewed='';const form=$('#ruleForm');form.oninput=()=>{$('#activateRule').disabled=true;previewed='';$('#rulePreview').innerHTML=''};$('#ruleKind').onchange=()=>{const k=$('#ruleKind').value;const presets={document:['documents','Exact attachment name, such as Passport.'],before:['submitted_at','Second date field, such as effective_date.'],different:['requester','Other record field, such as approver.'],employee:['employee_id','Employee register reference; no comparison value needed.'],approval:['amount','Numeric threshold; HR director approval is required above it.'],minimum:['amount','A numeric minimum, such as 0.'],maximum:['amount','A numeric maximum, such as 15000.']};$('#ruleField').value=presets[k][0];$('#valueHint').textContent=presets[k][1];$('#ruleValue').required=k!=='employee';$('#valueField').hidden=k==='employee';$('#ruleValue').value='';};$('#previewRule').onclick=()=>{if(!form.reportValidity())return;try{const r=validateRule(ruleDraft());if(['different','before'].includes(r.kind)&&!fields.includes(r.value))throw Error('The comparison value must be one of the supported record fields.');if(r.kind==='document'&&r.field!=='documents')throw Error('Document rules must use the documents field.');const p=evaluate(transactions,employees,[r]);$('#rulePreview').innerHTML=`<div class="rule-test-result"><strong>Preview across ${fmt(transactions.length)} transactions</strong><br>${fmt(p.counts.exception)} exceptions · ${fmt(p.counts.unknown)} evidence gaps · ${fmt(p.counts.pass)} passed · ${fmt(p.counts.notApplicable)} not applicable.<br>Confirm the condition faithfully matches the written policy before activating.</div>`;$('#ruleError').innerHTML='';previewed=JSON.stringify(r);$('#activateRule').disabled=false;}catch(err){$('#ruleError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`}};form.onsubmit=e=>{e.preventDefault();try{const r=validateRule(ruleDraft());if(JSON.stringify(r)!==previewed)throw Error('Preview the current rule before approving it.');rules.push(r);log('New policy approved',`${r.id} · ${r.title} · v1`,{rule:r});runChecks();closeDrawer();render();toast(`${r.id} activated. All transactions checked against the new rule.`);}catch(err){$('#ruleError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`}};}
function modal(title,content,buttons=''){const returnFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div style="display:flex;justify-content:space-between;gap:10px"><h2 id="modalTitle">${title}</h2><button class="icon-button" id="closeModal" aria-label="Close">${icon('close')}</button></div>${content}<div class="drawer-actions">${buttons||'<button class="btn primary" id="dismissModal">Understood</button>'}</div></section></div>`;document.body.style.overflow='hidden';const close=()=>{$('#modalRoot').innerHTML='';document.body.style.overflow='';returnFocus?.isConnected&&returnFocus.focus()};$('#closeModal').onclick=close;if($('#dismissModal'))$('#dismissModal').onclick=close;$('#closeModal').focus();return close;}
function toggleRule(id){const r=rules.find(r=>r.id===id);if(r.active&&rules.filter(r=>r.active).length===1){toast('Keep at least one active policy.');return;}const close=modal(`${r.active?'Pause':'Activate'} this policy?`,`<p><strong>${esc(r.id)} · ${esc(r.title)}</strong></p><p>${r.active?'Pausing removes this check from coverage and the current findings queue.':'Activating applies this policy to every relevant transaction in the current batch.'} Prior review decisions remain in the audit trail.</p>`,`<button class="btn primary" id="confirmToggle">${r.active?'Pause policy':'Activate policy'}</button>`);$('#confirmToggle').onclick=()=>{r.active=!r.active;log(r.active?'Policy activated':'Policy paused',`${r.id} · ${r.title} · v${r.version}`);runChecks();close();render();toast('Policy updated and checks rerun.');};}
function resetDemo(){const close=modal('Reset the demo workspace?','<p>This clears locally saved review decisions, custom rules and audit history for this prototype. Export your evidence first if you need to keep it.</p>','<button class="btn" id="dismissModal">Keep workspace</button><button class="btn primary" id="confirmReset">Reset demo</button>');$('#confirmReset').onclick=()=>{({transactions,employees}=generateDemo());rules=structuredClone(defaultRules);reviews={};audit=[];datasetId='demo-v1';batchName='Synthetic HR transactions';runChecks();close();location.hash='overview';render();toast('A fresh synthetic workspace is ready.');};}
function action(a){if(a==='upload')openUpload();if(a==='export')exportFindings();if(a==='samples')showSamples();if(a==='new-rule')openRuleBuilder();if(a==='rerun'){runChecks();render();toast('Checks complete. Previous review decisions are preserved.');}if(a==='policy-export'){download('policy_rules.md',policyMarkdown(),'text/markdown');toast('Policy wording and executable configuration exported.');}if(a==='audit-export'){download('aeris-audit-evidence.json',JSON.stringify({prototype:true,note:'Browser-local prototype history; not a tamper-resistant enterprise audit log.',exported_at:new Date().toISOString(),dataset:datasetId,batch:batchName,run_id:lastRunId,evaluated_at:lastRun,counts:results.counts,rules,findings:findings(),check_outcomes:results.outcomes,events:audit},null,2),'application/json');log('Audit evidence exported','Current rules, check outcomes, finding evidence and review events exported.');toast('Audit evidence exported.');}if(a==='reset')resetDemo();}
$('#helpButton').onclick=()=>modal('Meet your compliance workspace.','<p>Aeris checks every supplied HR transaction against approved rules, explains exceptions with evidence, and routes them for human review.</p><ul><li>Start with the priority queue and open a finding.</li><li>Read its policy, data evidence and suggested next step.</li><li>Assign an owner and record a human decision.</li><li>Import synthetic files or create and preview a policy.</li></ul><p>This prototype uses illustrative policies and generated data. It has no live Emirates connection or generative AI service.</p>');
$('#workspaceInfo').onclick=()=>modal('Emirates Group · Demo workspace','<p>This is an independent prototype for the supplied HR compliance challenge. All employees and transactions are synthetic; policy thresholds are illustrative.</p><p>The workspace is configured for a compliance analyst. Pilot deployment would add authenticated users, roles and shared audit storage.</p>');
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modalRoot').children.length)$('#closeModal')?.click();else if(!$('#drawer').hidden)closeDrawer();}if(e.key==='Tab'){const container=$('#modalRoot').children.length?$('.modal'):!$('#drawer').hidden?$('#drawer'):null;if(container){const focus=$$('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]',container).filter(e=>e.getClientRects().length);if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});

// Durable, privacy-preserving workspace and operational review workflow.
let batches=[],protectedData=false,serverVersion=0,session={id:'local-reviewer',name:'Local reviewer',mode:'local'},storageState='Loading vault…',saveTimer,pendingEvents=[],saveChain=Promise.resolve(),replayTimer=null,replayIndex=0,exportSchema=null,filterOwner='All owners',filterTeam='All teams',persona='analyst',activePerson='compliance';
const staff=[{id:'compliance',name:'Maya Rahman',team:'HR Compliance',role:'analyst'},{id:'payroll',name:'Omar Ali',team:'Payroll Operations',role:'operations'},{id:'talent',name:'Sara Khan',team:'Talent Acquisition',role:'operations'},{id:'operations',name:'Ravi Shah',team:'HR Operations',role:'operations'},{id:'services',name:'Noor Hassan',team:'Employee Services',role:'operations'},{id:'audit',name:'Daniel Thomas',team:'Internal Audit',role:'audit'}];
const acting=()=>staff.find(p=>p.id===activePerson)||staff[0];
function vault(){return new Promise((resolve,reject)=>{const request=indexedDB.open('aeris-private-vault-v2',1);request.onupgradeneeded=()=>request.result.createObjectStore('workspace');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function vaultRead(){const db=await vault();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readonly'),r=tx.objectStore('workspace').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close();});}
async function vaultWrite(value){const db=await vault();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(value,'current');tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error);});}
function captureBatch(){if(!results)return;let b=batches.find(x=>x.id===datasetId);if(!b){b={id:datasetId,name:batchName,source:datasetId==='demo-v1'?'demo':'generated',createdAt:new Date().toISOString(),runs:[]};batches.push(b);}Object.assign(b,{name:batchName,transactions,employees,rules:structuredClone(rules),lastRun,lastRunId,counts:results.counts});}
function snapshot(){captureBatch();return {schemaVersion:2,protectedData,activeBatchId:datasetId,batches,reviews,audit,exportSchema,replayIndex,updatedAt:new Date().toISOString()};}
function storageBanner(){return `<div class="vault-banner ${protectedData?'private-vault':''}">${icon(protectedData?'lock':'shield')}<span><strong>${protectedData?'Device-local private vault':'Generated demo workspace'}</strong> · <span id="vaultSaveState">${esc(storageState)}</span>${protectedData?' · Imported files, evidence and notes are never uploaded.':''}</span><a href="#batches">Batch history ${icon('arrow')}</a></div>`;}
function refreshStorageLabel(){for(const id of ['#saveState','#vaultSaveState']){const label=$(id);if(label)label.textContent=storageState;}}
persist=function(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const data=snapshot();saveChain=saveChain.then(async()=>{try{await vaultWrite(data);storageState=protectedData?'Saved on this device; server sync paused':'Saved locally';if(!protectedData){const response=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({synthetic:true,workspace:data,expectedVersion:serverVersion,events:pendingEvents})});if(response.status===409){storageState='Saved locally; another session changed. Reload to reconcile.';}else if(response.ok){const result=await response.json();serverVersion=result.version;pendingEvents=[];storageState='Saved · private server and device';}else storageState='Saved on this device; server unavailable';}refreshStorageLabel();}catch(err){storageState='Save failed — export a workspace backup';refreshStorageLabel();toast(storageState);}});},160);return true;};
log=function(action,detail,meta={}){const event={id:crypto.randomUUID(),timestamp:new Date().toISOString(),actor:`${session.name} · ${acting().name} (demo role)`,actor_id:session.id,persona,acting_person:activePerson,action,detail,dataset:datasetId,...meta};audit.push(event);pendingEvents.push(event);persist();};
const baseRunChecks=runChecks;
runChecks=function(record=true){baseRunChecks(record);captureBatch();if(record){const b=batches.find(x=>x.id===datasetId);b.runs.push({id:lastRunId,at:lastRun,counts:structuredClone(results.counts),rules:structuredClone(rules)});persist();}};
const baseFindingKey=findingKey;
findingKey=function(f){return baseFindingKey(f);};
findings=function(){const batch=batches.find(b=>b.id===datasetId),detected=batch?.createdAt||lastRun;return results.findings.map(f=>{const previous=reviews[findingKey(f)]||{},person=staff.find(p=>p.team===(previous.owner||f.owner))||staff[3],openedAt=previous.opened_at||detected;return {...f,case_owner:person.id,case_owner_name:person.name,opened_at:openedAt,due_date:new Date(new Date(openedAt).getTime()+({Critical:1,High:3,Medium:7,Low:14}[f.severity]||7)*86400000).toISOString().slice(0,10),...previous};}).sort((a,b)=>severityRank[a.severity]-severityRank[b.severity]||String(a.due_date).localeCompare(b.due_date)||a.id.localeCompare(b.id));};
const baseNav=nav;
nav=function(){baseNav();const extra=[['batches','folder','Batch history'],['leads','spark','Investigation leads']];$('#nav').insertAdjacentHTML('beforeend',extra.map(([key,i,label])=>`<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''} title="${label}">${icon(i)}<span class="nav-text">${label}</span></a>`).join(''));if(extra.some(x=>x[0]===route))$('#breadcrumb').textContent=extra.find(x=>x[0]===route)[2];};
function contextBar(){return `<div class="context-bar"><div><span class="context-label">REVIEW CONTEXT · DEMO</span><select id="personaSelect" aria-label="Review context"><option value="analyst" ${persona==='analyst'?'selected':''}>Compliance analyst</option><option value="operations" ${persona==='operations'?'selected':''}>Operations owner</option><option value="audit" ${persona==='audit'?'selected':''}>Internal audit · read only</option></select></div><div><span class="context-label">ACTING AS · SYNTHETIC STAFF</span><select id="personSelect" aria-label="Acting demo staff">${staff.filter(p=>p.role===persona).map(p=>`<option value="${p.id}" ${p.id===activePerson?'selected':''}>${p.name} · ${p.team}</option>`).join('')}</select></div><span id="saveState">${esc(storageState)}</span></div>`;}
const baseRender=render;
render=function(){if(!results)return;nav();const screens={batches:batchesPage,leads:leadsPage};if(screens[route]){$('#main').innerHTML=screens[route]();bindMain();hydrateIcons();}else baseRender();$('#main').insertAdjacentHTML('afterbegin',storageBanner()+contextBar());$('#personaSelect').onchange=e=>{persona=e.target.value;activePerson=staff.find(p=>p.role===persona).id;filterOwner=persona==='operations'?activePerson:'All owners';render()};$('#personSelect').onchange=e=>{activePerson=e.target.value;if(persona==='operations')filterOwner=activePerson;render()};$$('[data-batch]').forEach(b=>b.onclick=()=>switchBatch(b.dataset.batch));$$('[data-run]').forEach(b=>b.onclick=()=>openRun(b.dataset.run));$$('[data-lead]').forEach(b=>b.onclick=()=>openLead(b.dataset.lead));};
const baseTransactionPage=transactionPage;
transactionPage=function(){return baseTransactionPage().replace('Imported records are held in this tab only. Reloading restores the demo batch.','This batch is retained in the device-local vault across reloads. Files are never uploaded.');};
const baseAuditPage=auditPage;
auditPage=function(){return baseAuditPage().replace('Decisions are saved in this browser. This is a reviewable activity record; an enterprise pilot needs authenticated identities and tamper-resistant server storage.','Retained batches preserve rule snapshots and evidence. Imported-pack events stay in your device vault. Generated-demo events also have server-recorded identity and a hash-linked event trail. Export a workspace backup for portable review.');};
exceptionFiltered=function(){return findings().filter(f=>(tab==='all'||tab==='gaps'&&f.evaluation==='unknown'||tab==='policy'&&f.evaluation==='exception')&&(['All severities','All'].includes(filterSeverity)||f.severity===filterSeverity)&&(['All statuses','All'].includes(filterStatus)||f.status===filterStatus)&&(['All processes','All'].includes(filterProcess)||f.process===filterProcess)&&(filterOwner==='All owners'||f.case_owner===filterOwner)&&(filterTeam==='All teams'||f.owner===filterTeam)&&`${f.title} ${f.transaction_id} ${f.employee_name} ${f.department} ${f.rule_id} ${f.owner} ${f.case_owner_name}`.toLowerCase().includes(query.toLowerCase()));};
findingRows=function(rows,full=false){return rows.map(f=>`<tr class="clickable" tabindex="0" data-finding="${esc(f.id)}" aria-label="Review ${esc(f.title)} for ${esc(f.transaction_id)}"><td><span class="finding-name">${esc(f.title)}</span><span class="subcell">${esc(f.transaction_id)} · ${esc(f.process)}</span></td>${full?`<td><span class="finding-name">${esc(f.employee_name)}</span><span class="subcell">${esc(f.department)}</span></td>`:''}<td>${badge(f.severity)}</td><td><span class="rule-code">${esc(f.rule_id)}</span></td>${full?`<td>${badge(f.status)}<span class="subcell">Due ${dateFmt(f.due_date)} · ${Math.max(0,Math.floor((Date.now()-new Date(f.opened_at))/86400000))}d open</span></td>`:''}<td><div class="owner-cell"><span class="owner-avatar">${esc(f.case_owner_name.split(' ').map(x=>x[0]).join(''))}</span><span>${esc(f.case_owner_name)}<span class="subcell">${esc(f.owner)}</span></span></div></td><td class="arrow-cell">${icon('chevron')}</td></tr>`).join('');};
const baseExceptions=exceptions;
exceptions=function(){let html=baseExceptions();html=html.replace("['Open','Review','Resolved','Dismissed']", "['Open','Review','Fix submitted','Clarification requested','Resolved','Dismissed']");const statusSelect=`<select id="statusFilter" aria-label="Filter status">${['All statuses','Open','Review','Clarification requested','Fix submitted','Resolved','Dismissed'].map(s=>`<option ${s===filterStatus?'selected':''}>${s}</option>`).join('')}</select>`;html=html.replace(/<select id="statusFilter"[\s\S]*?<\/select>/,statusSelect);const extra=`<div class="toolbar owner-toolbar"><select id="ownerFilter" aria-label="Accountable owner"><option value="All owners">All owners</option>${staff.filter(p=>p.role!=='audit').map(p=>`<option value="${p.id}" ${filterOwner===p.id?'selected':''}>${p.name}</option>`).join('')}</select><select id="teamFilter" aria-label="Assigned team">${['All teams',...owners].map(t=>`<option ${filterTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="btn small" data-action="my-queue">My assigned queue</button><span class="results-label">Severity → earliest due date · due dates are demo service targets</span></div>`;return html.replace('<section class="panel">',extra+'<section class="panel">');};
const baseBind=bindMain;
bindMain=function(){baseBind();if($('#ownerFilter'))$('#ownerFilter').onchange=e=>{filterOwner=e.target.value;page=1;render()};if($('#teamFilter'))$('#teamFilter').onchange=e=>{filterTeam=e.target.value;page=1;render()};};
function batchesPage(){return heading('A CONTINUOUS RECORD','Every batch. <em>Ready to revisit.</em>','Retained source records, policy snapshots and check runs. Reimporting the same files reopens the existing batch.',secondary('Workspace backup','backup')+secondary('Restore backup','restore','upload')+primary('Import synthetic batch','upload','upload'))+`<div class="info-banner">${icon('lock')}<span>Uploaded packs stay on this device. Each batch retains its employee register, policy configuration and review history. Download a workspace backup before clearing browser data.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Transactions</th><th>Policy exceptions</th><th>Evidence gaps</th><th>Latest check</th><th></th></tr></thead><tbody>${batches.map(b=>`<tr><td><span class="finding-name">${esc(b.name)} ${b.id===datasetId?'<span class="counter">Current</span>':''}</span><span class="subcell">${b.source==='imported'?'Private device vault':'Generated synthetic demo'} · ${b.runs?.length||1} check runs</span></td><td>${fmt(b.transactions.length)}</td><td>${fmt(b.counts?.exception||0)}</td><td>${fmt(b.counts?.unknown||0)}</td><td>${timeFmt(b.lastRun)}</td><td><button class="btn small" data-batch="${esc(b.id)}">Open batch</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel replay-panel"><div><div class="eyebrow">REPEATABLE COVERAGE</div><h2 class="panel-title">Successive-batch demonstration</h2><p class="subtitle">Replay three successive generated batches. Each is checked once and retained separately. Existing transaction/rule findings are reused when a batch is replayed.</p><p class="panel-subtitle">Browser demonstration only. Playback pauses when you close this tab; production scheduling belongs inside the enterprise environment.</p></div><div class="drawer-actions">${primary(replayTimer?'Pause replay':'Start replay','replay','refresh')}${secondary('Ingest next demo batch','replay-one','plus')}</div></section><section class="panel runs-panel"><div class="panel-header"><h2 class="panel-title">Check runs · ${esc(batchName)}</h2></div><div class="activity-list">${(batches.find(b=>b.id===datasetId)?.runs||[]).slice().reverse().map(r=>`<div class="history-item"><button class="btn link" data-run="${esc(r.id)}">${timeFmt(r.at)} · ${fmt(r.counts.exception)} exceptions · ${r.rules.filter(p=>p.active).length} policies ${icon('arrow')}</button></div>`).join('')||'<p class="subtitle">Run history will appear after the next check.</p>'}</div></section>`;}
function switchBatch(id){captureBatch();const b=batches.find(x=>x.id===id);if(!b)return;({transactions,employees,rules}=structuredClone(b));datasetId=b.id;batchName=b.name;lastRun=b.lastRun;lastRunId=b.lastRunId;results=evaluate(transactions,employees,rules);query='';page=1;persist();render();toast(`Opened ${b.name}. Previous decisions are retained.`);}
function openRun(id){const run=batches.find(b=>b.id===datasetId)?.runs.find(r=>r.id===id);if(!run)return;const oldResults=evaluate(transactions,employees,run.rules);drawer('A reproducible check run.',`<p class="subtitle">${timeFmt(run.at)} · ${esc(id)}</p><div class="stat-inline"><div><strong>${fmt(oldResults.counts.exception)}</strong><small>Policy exceptions</small></div><div><strong>${fmt(oldResults.counts.unknown)}</strong><small>Evidence gaps</small></div></div><div class="info-banner">${icon('book')}This run uses its preserved policy configuration. Reproduction does not change the active batch or its reviews.</div><table class="evidence"><tbody>${run.rules.filter(r=>r.active).map(r=>`<tr><td>${esc(r.id)} · v${r.version}</td><td>${esc(r.text)}</td></tr>`).join('')}</tbody></table><div class="drawer-actions"><button class="btn primary" id="exportRun">Export this run's evidence</button></div>`,'HISTORICAL POLICY SNAPSHOT');$('#exportRun').onclick=()=>download('aeris-run-'+id+'.json',JSON.stringify({batch_id:datasetId,run,counts:oldResults.counts,findings:oldResults.findings,outcomes:oldResults.outcomes},null,2),'application/json');}
async function replayOne(){captureBatch();replayIndex=(replayIndex%3)+1;const id='replay-v1-'+replayIndex,old=batches.find(b=>b.id===id);if(old){switchBatch(id);return;}const data=generateDemo();transactions=data.transactions.slice((replayIndex-1)*150,(replayIndex)*150).map((t,i)=>({...t,transaction_id:`REPLAY-${replayIndex}-${String(i+1).padStart(4,'0')}`}));employees=data.employees;datasetId=id;batchName=`Continuous demo · batch ${replayIndex}`;const b={id,name:batchName,source:'generated',createdAt:new Date().toISOString(),runs:[]};batches.push(b);log('Generated batch ingested',`${transactions.length} synthetic transactions · replay sequence ${replayIndex}`);runChecks();render();}
function toggleReplay(){if(replayTimer){clearInterval(replayTimer);replayTimer=null;render();toast('Replay paused. Retained batches remain available.');}else{replayOne();let remaining=2;replayTimer=setInterval(()=>{replayOne();if(--remaining===0){clearInterval(replayTimer);replayTimer=null;render();toast('Three generated batches checked and retained.');}},5000);render();}}
function leads(){return intelligence.detectAnomalies?intelligence.detectAnomalies(transactions,employees):[];}
function leadsPage(){const ls=leads();return heading('A REASON TO LOOK CLOSER','Unusual does not mean <em>noncompliant.</em>','Investigation leads are separate from policy exceptions and competition finding exports.',secondary('Export investigation leads','leads-export')+primary('Generate unusual example','lead-demo','spark'))+`<div class="info-banner">${icon('info')}<span>These statistical signals do not claim a policy breach or employee wrongdoing. Each lead cites its detector, comparison group and record evidence. A person decides whether further enquiry is justified.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Investigation lead</th><th>Transaction</th><th>Team</th><th>Detector</th><th></th></tr></thead><tbody>${ls.map(l=>`<tr><td><span class="finding-name">${esc(l.title)}</span></td><td>${esc(l.transaction_id)}</td><td>${esc(l.department)}</td><td><span class="rule-code">${esc(l.detector_id)} · v${esc(l.detector_version)}</span></td><td><button class="btn small" data-lead="${esc(l.id)}">Review lead</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty"><strong>No investigation leads in this batch.</strong>Small comparison groups and ordinary variation are not flagged.</div></td></tr>'}</tbody></table></div></section>`;}
function openLead(id){const l=leads().find(l=>l.id===id);if(!l)return;drawer(esc(l.title),`<div class="drawer-tags">${badge('Review')}<span class="rule-code">${esc(l.detector_id)} · v${esc(l.detector_version)}</span></div><div class="explanation-box">${esc(l.explanation)}</div><section class="detail-section"><h3>Detector evidence · not a policy breach</h3><table class="evidence"><tbody>${l.evidence.map(e=>`<tr><td>${esc(e.field)}</td><td>${esc(e.value)}</td></tr>`).join('')}</tbody></table><p>${esc(l.action)}</p></section><div class="info-banner">${icon('shield')}An unusual record must not trigger an adverse employee decision. Verify data quality, legitimate context and the employee's explanation first.</div><div class="form-field"><label for="leadNote">Investigation note</label><textarea id="leadNote" placeholder="Record whether more context is needed."></textarea></div><button class="btn primary" id="saveLead" ${persona==='audit'?'disabled':''}>Record human assessment</button>`,'INVESTIGATION LEAD');$('#saveLead').onclick=()=>{const note=$('#leadNote').value.trim();if(!note){toast('A reason is required.');return;}log('Investigation lead assessed',`${l.transaction_id} · ${l.detector_id}`,{detector_id:l.detector_id,detector_version:l.detector_version,evidence:l.evidence,note});closeDrawer();toast('Assessment recorded. No policy violation was inferred.');};}
openFinding=function(id){const f=findings().find(x=>x.id===id);if(!f)return;const history=audit.filter(a=>a.finding_id===id&&a.dataset===datasetId&&a.rule_version===f.rule_version).reverse(),readOnly=persona==='audit';let actions=persona==='operations'?['Record progress','Submit fix for verification','Request employee clarification']:['Record review','Request employee clarification','Dismiss with reason','Reopen for action'];if(persona==='analyst'&&f.status==='Fix submitted')actions.unshift('Verify and close');const old=reviews[findingKey(f)]||{};drawer(esc(f.title),`<div class="drawer-tags">${badge(f.severity)}${badge(f.status)}<span class="rule-code" style="margin-left:auto">${esc(f.rule_id)} · v${f.rule_version}</span></div><div class="explanation-box">${esc(f.explanation)}</div><div class="meta-grid"><div><small>TRANSACTION / EMPLOYEE</small><strong>${esc(f.transaction_id)} · ${esc(f.employee_id)}</strong></div><div><small>ACCOUNTABLE OWNER</small><strong>${esc(f.case_owner_name)} · ${esc(f.owner)}</strong></div><div><small>PROCESS / TEAM</small><strong>${esc(f.process)} · ${esc(f.department)}</strong></div><div><small>DUE DATE · DEMO TARGET</small><strong>${dateFmt(f.due_date)}</strong></div></div><section class="detail-section"><h3>The policy behind this check</h3><p>${esc(f.policy)}</p><span class="subcell">${esc(f.rule_id)} · version ${f.rule_version} · ${f.evaluation==='unknown'?'Evidence gap; not a confirmed violation':'Rule-based exception'}</span></section><section class="detail-section"><h3>Evidence from the record</h3><table class="evidence"><tbody>${f.evidence.map(e=>`<tr><td>${esc(e.field)}</td><td>${esc(e.value)}</td></tr>`).join('')}</tbody></table></section><section class="detail-section"><h3>Suggested next step</h3><p>${esc(f.action)}</p>${old.fix_evidence?`<div class="inline-success"><strong>Owner's submitted fix evidence:</strong><br>${esc(old.fix_evidence)}<br><small>Submitted by ${esc(staff.find(p=>p.id===old.fix_submitted_by)?.name||old.fix_submitted_by)} · ${timeFmt(old.fix_submitted_at)}</small></div>`:''}</section><section class="detail-section"><h3>Fair handling and employee context</h3><p>Describe the record, not the person's intent. Check whether data is incomplete or an authorised exception applies. Ask the employee only for information necessary to clarify this finding. Record their explanation and allow a correction or appeal before any consequential decision.</p>${old.employee_context?`<div class="explanation-box">${esc(old.employee_context)}</div>`:''}</section>${readOnly?'<div class="info-banner">Read-only audit context. Switch review context to record an operational or compliance decision.</div>':`<section class="detail-section"><h3>Human decision</h3><form id="reviewForm"><div class="form-row"><div class="form-field"><label for="reviewOwner">Assigned team</label><select id="reviewOwner">${owners.map(o=>`<option ${o===f.owner?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div class="form-field"><label for="reviewPerson">Accountable case owner</label><select id="reviewPerson">${staff.filter(p=>p.role!=='audit').map(p=>`<option value="${p.id}" ${p.id===f.case_owner?'selected':''}>${p.name}</option>`).join('')}</select></div></div><div class="form-field"><label for="reviewDecision">Action</label><select id="reviewDecision">${actions.map(a=>`<option>${a}</option>`).join('')}</select></div><div class="form-field"><label for="reviewNote">Decision reason / review note</label><textarea id="reviewNote" required placeholder="Explain your decision and the evidence considered."></textarea></div><div class="form-field"><label for="fixEvidence">Fix evidence or reference</label><textarea id="fixEvidence" placeholder="Required to submit a fix: correction reference, approved document ID, or an evidence summary.">${esc(old.fix_evidence||'')}</textarea><small>A note alone cannot close a finding. An operations owner submits evidence; a different compliance reviewer verifies it.</small></div><div class="form-field"><label for="employeeContext">Employee explanation / clarification / appeal</label><textarea id="employeeContext" placeholder="Record relevant context neutrally, without unnecessary personal information.">${esc(old.employee_context||'')}</textarea></div><div id="reviewError"></div><div class="drawer-actions"><button class="btn primary" type="submit">${icon('check')}Save human decision</button><button type="button" class="btn" id="viewTransaction">View transaction</button></div></form></section>`}<section class="detail-section"><h3>Finding history</h3>${history.map(h=>`<div class="history-item"><strong>${esc(h.action)}</strong><div>${esc(h.detail)}</div>${h.note?`<div>${esc(h.note)}</div>`:''}<small>${timeFmt(h.timestamp)} · ${esc(h.actor)}</small></div>`).join('')||'<p>No decisions recorded yet.</p>'}</section>`);if($('#viewTransaction'))$('#viewTransaction').onclick=()=>openTransaction(f.transaction_id);if(!readOnly)$('#reviewForm').onsubmit=e=>{e.preventDefault();const note=$('#reviewNote').value.trim(),decision=$('#reviewDecision').value,evidence=$('#fixEvidence').value.trim(),context=$('#employeeContext').value.trim();try{if(!note)throw Error('A decision reason is required.');let status=f.status,extra={};if(decision==='Submit fix for verification'){if(persona!=='operations')throw Error('An operations owner must submit the fix.');if(!evidence)throw Error('Provide the fix evidence or reference before submission.');status='Fix submitted';extra={fix_evidence:evidence,fix_submitted_by:activePerson,fix_submitted_at:new Date().toISOString()};}if(decision==='Verify and close'){if(persona!=='analyst'||f.status!=='Fix submitted'||!old.fix_evidence)throw Error('A submitted fix with supporting evidence is required before closure.');if(old.fix_submitted_by===activePerson)throw Error('The person who submitted the fix cannot verify closure.');status='Resolved';extra={verified_by:activePerson,verified_at:new Date().toISOString()};}if(decision==='Request employee clarification'){if(!context)throw Error('Record the clarification request or employee context.');status='Clarification requested';}if(decision==='Dismiss with reason')status='Dismissed';if(decision==='Reopen for action')status='Open';if(decision==='Record review'||decision==='Record progress')status='Review';const person=staff.find(p=>p.id===$('#reviewPerson').value);reviews[findingKey(f)]={...old,owner:$('#reviewOwner').value,case_owner:person.id,case_owner_name:person.name,opened_at:f.opened_at,due_date:f.due_date,status,employee_context:context,reviewed_at:new Date().toISOString(),...extra};log(decision,`${f.transaction_id} · ${f.rule_id}: ${f.status} → ${status}`,{finding_id:f.id,note,status,previous_status:f.status,owner:$('#reviewOwner').value,case_owner:person.id,rule_id:f.rule_id,rule_version:f.rule_version,policy:f.policy,evidence:f.evidence,fix_evidence:extra.fix_evidence||old.fix_evidence||'',employee_context:context});closeDrawer();render();toast('Human decision recorded. No employee transaction was changed.');}catch(err){$('#reviewError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`;}};};
function issueText(issue){return typeof issue==='string'?issue:issue.message||issue.reason||JSON.stringify(issue);}
function policyDraftReview(text,onApprove){if(!intelligence.compilePolicyText){toast('Policy compiler is loading. Use the guided rule editor.');return;}const startId=Math.max(...rules.map(r=>Number(String(r.id).replace(/\D/g,''))||0),0)+1;const compiled=intelligence.compilePolicyText(text,{startId});const drafts=(compiled.rules||[]).map((r,i)=>({...r,id:r.id||`POL-${String(startId+i).padStart(3,'0')}`,version:r.version||1,active:true,source:'Human-approved written policy'}));drawer('Written policy, made explicit.',`<p class="subtitle">The compiler supports explicit policy patterns. Review the executable interpretation and unresolved text before approval. No model service is used.</p><div class="info-banner">${icon('lock')}This policy remains in the device-local vault. No policy text is uploaded.</div>${compiled.issues?.length?`<div class="inline-error"><strong>${compiled.issues.length} statement(s) need clarification.</strong>${compiled.issues.map(i=>`<p>${esc(issueText(i))}</p>`).join('')}Unsupported or ambiguous statements are not executed. Use the guided editor after clarification.</div>`:''}${drafts.map(r=>{let p;try{p=evaluate(transactions,employees,[r]);}catch{return `<div class="inline-error">${esc(r.title)} cannot be evaluated.</div>`;}return `<section class="detail-section"><h3>${esc(r.id)} · ${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="rule-test-result">${esc(r.kind)} · field ${esc(r.field)} · comparison ${esc(JSON.stringify(r.value))}<br>${fmt(p.counts.exception)} exceptions · ${fmt(p.counts.unknown)} evidence gaps · ${fmt(p.counts.notApplicable)} not applicable.</div></section>`}).join('')}<div class="drawer-actions"><button class="btn primary" id="approvePolicyDraft" ${!drafts.length?'disabled':''}>Approve ${drafts.length} supported rules</button><button class="btn" id="guidedPolicy">Open guided editor</button></div><p class="subtitle">Approval accepts only the listed executable rules. Unresolved statements remain pending and are included in the audit record.</p>`,'POLICY INTERPRETATION & HUMAN APPROVAL');$('#guidedPolicy').onclick=()=>baseOpenRuleBuilder();$('#approvePolicyDraft').onclick=()=>{protectedData=true;onApprove(drafts,compiled.issues||[]);};}
const baseOpenRuleBuilder=openRuleBuilder;
openRuleBuilder=function(){drawer('Add a policy without code.',`<p class="subtitle">Write or paste clear English policies. The compiler turns supported statements into draft conditions for your review.</p><div class="form-field"><label for="plainPolicy">Policy wording</label><textarea id="plainPolicy" rows="7" placeholder="Every hire requires an Offer letter attachment.&#10;The requester and approver must be different people.&#10;An allowance above AED 5,000 requires HR director approval."></textarea></div><div class="info-banner">${icon('info')}Supported patterns include explicit document requirements, approval thresholds, field comparisons, timing windows and independent approval. Ambiguous wording requires clarification; it is never silently approved.</div><div class="drawer-actions"><button class="btn primary" id="compilePolicy">Interpret & preview</button><button class="btn" id="openGuided">Use guided condition editor</button></div>`,'PLAIN ENGLISH POLICY');$('#openGuided').onclick=()=>{protectedData=true;baseOpenRuleBuilder();};$('#compilePolicy').onclick=()=>{const text=$('#plainPolicy').value.trim();if(!text){toast('Enter the written policy first.');return;}protectedData=true;policyDraftReview(text,(drafts,issues)=>{const ids=new Set(rules.map(r=>r.id));for(const r of drafts){while(ids.has(r.id))r.id='POL-'+String(Math.max(...[...ids].map(id=>Number(id.replace(/\D/g,''))||0))+1).padStart(3,'0');ids.add(r.id);rules.push(r);}log('Written policies approved',`${drafts.length} supported rules activated; ${issues.length} statements pending clarification.`,{rules:drafts,unresolved_policy_statements:issues});runChecks();closeDrawer();render();toast('Approved policies activated; all transactions checked.');});};};
openUpload=function(){drawer('A new batch. A complete check.',`<p class="subtitle">Import synthetic files into your private device vault. Files and their derived evidence are never uploaded to the hosted service.</p><form id="uploadForm"><div class="upload-zone">${icon('upload')}<h3>Transaction CSV</h3><input id="txFile" type="file" accept=".csv,text/csv" required aria-label="Transaction CSV"></div><div class="form-field"><label for="employeeFile">Employee register · CSV</label><input id="employeeFile" type="file" accept=".csv,text/csv" required></div><div class="form-field"><label for="policyFile">Written policy or structured configuration · optional</label><input id="policyFile" type="file" accept=".md,.txt,.json"><small>Plain English / Markdown is interpreted into drafts for approval. Structured JSON is validated and previewed. Without a file, the current approved rules apply.</small></div><div class="form-field"><label for="formatFile">finding_format.csv · optional official output template</label><input id="formatFile" type="file" accept=".csv"><small>Only headers define the output layout. Worked example rows are not imported as findings.</small></div><label class="check-label"><input id="syntheticConsent" type="checkbox" required>I confirm that all uploaded data is synthetic. Files must remain on this device.</label><div id="uploadError"></div><div class="drawer-actions"><button class="btn primary" type="submit">Validate & preview</button><button type="button" class="btn" id="getSample">Download example files</button></div></form><section class="detail-section"><h3>Required fields</h3><p>Transactions: transaction_id, employee_id, type, effective_date. Policy evidence uses amount, grade, department, requester, approver, approver_role, submitted_at, approved_at, documents. Employees require employee_id. Dates use ISO format; documents use semicolon-separated names.</p></section>`,'PRIVATE BATCH IMPORT');$('#getSample').onclick=showSamples;$('#uploadForm').onsubmit=async e=>{e.preventDefault();try{const txf=$('#txFile').files[0],emf=$('#employeeFile').files[0],pf=$('#policyFile').files[0],ff=$('#formatFile').files[0];for(const file of [txf,emf,pf,ff].filter(Boolean))if(file.size>15*1024*1024)throw Error(`${file.name} exceeds 15 MB.`);const txText=await txf.text(),emText=await emf.text(),newTx=validateRows(parseCSV(txText),'transactions'),newEm=validateRows(parseCSV(emText),'employees');if(newTx.length>100000)throw Error('Browser batches are limited to 100,000 transactions.');let format=null;if(ff){const raw=await ff.text();format=parseCSV(raw);format={name:ff.name,headers:readCSVHeaders(raw),mapping:{}};if(!format.headers.length)throw Error('The finding template has no headers.');}
const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(txText+'\n'+emText));const newId='batch-'+[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');const finish=(newRules=rules,issues=[])=>{captureBatch();protectedData=true;const existing=batches.find(b=>b.id===newId);if(existing){if(format)exportSchema=format;switchBatch(newId);closeDrawer();location.hash='overview';render();toast('Identical files detected. Reopened retained batch without duplicate findings.');return;}transactions=newTx;employees=newEm;rules=structuredClone(newRules);datasetId=newId;batchName=txf.name;batches.push({id:newId,name:batchName,source:'imported',createdAt:new Date().toISOString(),runs:[],policyIssues:issues});if(format)exportSchema=format;log('Private synthetic batch imported',`${txf.name} · ${newTx.length} transactions · device-local vault`,{unresolved_policy_statements:issues});runChecks();closeDrawer();location.hash='overview';render();toast('Batch checked and retained privately on this device.');};
if(pf){const raw=await pf.text();protectedData=true;const json=pf.name.endsWith('.json')?raw:raw.match(/```json\s*([\s\S]*?)```/i)?.[1];if(json){const rs=JSON.parse(json);if(!Array.isArray(rs)||!rs.length||rs.length>100)throw Error('Supply 1–100 structured rules.');const ids=new Set();const validated=rs.map(r=>{if(!r.id||ids.has(r.id))throw Error('Each policy needs a unique ID.');ids.add(r.id);return validateRule({...r,active:r.active!==false,version:r.version||1});});const preview=evaluate(newTx,newEm,validated);drawer('Approve the policy set.',`<p>${validated.length} rules will produce ${preview.counts.exception} exceptions and ${preview.counts.unknown} evidence gaps across ${newTx.length} transactions.</p><table class="evidence"><tbody>${validated.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.text)}</td></tr>`).join('')}</tbody></table><div class="drawer-actions"><button id="approveImport" class="btn primary">Approve policies & check batch</button></div>`,'HUMAN POLICY APPROVAL');$('#approveImport').onclick=()=>finish(validated);}else{const oldTx=transactions,oldEm=employees;transactions=newTx;employees=newEm;policyDraftReview(raw,(rs,issues)=>{transactions=oldTx;employees=oldEm;finish(rs,issues);});transactions=oldTx;employees=oldEm;}}else finish();}catch(err){const box=$('#uploadError');if(box)box.innerHTML=`<div class="inline-error">${esc(err.message)}</div>`;else toast(err.message);}};};
const exportFields=['finding_id','transaction_id','employee_id','process','department','rule_id','rule_version','severity','status','owner','case_owner_name','explanation','policy_text','evidence','suggested_action','evaluated_at','dataset','evaluation'];
function exportRows(fs){return fs.map(f=>({finding_id:f.id,transaction_id:f.transaction_id,employee_id:f.employee_id,process:f.process,department:f.department,rule_id:f.rule_id,rule_version:f.rule_version,severity:f.severity,status:f.status,owner:f.owner,case_owner_name:f.case_owner_name,explanation:f.explanation,policy_text:f.policy,evidence:JSON.stringify(f.evidence),suggested_action:f.action,evaluated_at:lastRun,dataset:datasetId,evaluation:f.evaluation}));}
function defaultMap(header){const normal=header.toLowerCase().replace(/[^a-z0-9]/g,'');const exact=exportFields.find(f=>f.replaceAll('_','')===normal);const aliases={rule:'rule_id',policy:'rule_id',transaction:'transaction_id',reason:'explanation',description:'explanation',action:'suggested_action',correctiveaction:'suggested_action',assignedto:'owner',finding:'finding_id',employee:'employee_id'};return exact||aliases[normal]||'';}
exportFindings=function(){const headers=exportSchema?.headers||exportFields;drawer('Export findings for review.',`<p class="subtitle">${exportSchema?'Output uses the exact uploaded template headers and order. Review every mapping before export.':'The official template has not been supplied. Upload finding_format.csv with a batch to map its exact headers.'}</p><div class="form-field"><label for="exportScope">Include</label><select id="exportScope"><option value="policy">Confirmed policy exceptions only</option><option value="gaps">Evidence gaps only</option><option value="all">Both · includes evaluation classification</option></select></div>${exportSchema?`<div class="detail-section"><h3>Official template: ${esc(exportSchema.name)}</h3>${headers.map((h,i)=>`<div class="form-field"><label for="map-${i}">${esc(h)}</label><select id="map-${i}" data-map="${i}"><option value="">Choose a source field…</option>${exportFields.map(f=>`<option value="${f}" ${(exportSchema.mapping[h]||defaultMap(h))===f?'selected':''}>${f}</option>`).join('')}</select></div>`).join('')}</div>`:''}<div class="info-banner">${icon('info')}Investigation leads are never included in policy finding exports. Worked template examples never become generated findings.</div><div id="exportError"></div><div class="drawer-actions"><button class="btn primary" id="confirmExport">Confirm mapping & download CSV</button></div>`,'FINDING FORMAT & EXPORT');$('#confirmExport').onclick=()=>{try{const scope=$('#exportScope').value,fs=(route==='exceptions'?exceptionFiltered():findings()).filter(f=>scope==='all'||f.evaluation===(scope==='gaps'?'unknown':'exception')),rows=exportRows(fs);let mapping={};if(exportSchema){headers.forEach((h,i)=>{const value=$('#map-'+i).value;if(!value)throw Error(`Map the “${h}” column before export.`);mapping[h]=value;});exportSchema.mapping=mapping;}else mapping=Object.fromEntries(headers.map(h=>[h,h]));const mapped=rows.map(r=>Object.fromEntries(headers.map(h=>[h,r[mapping[h]]??''])));download('aeris-findings.csv',toCSV(mapped,headers),'text/csv;charset=utf-8');log('Findings exported',`${fs.length} ${scope} findings · ${exportSchema?.name||'prototype schema'}`,{mapping,headers});closeDrawer();render();toast(`${fs.length} findings exported with the confirmed column mapping.`);}catch(err){$('#exportError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`;}};};
const baseSettings=settingsPage;
settingsPage=function(){return heading('A RESPONSIBLE FOUNDATION','Trust is part <em>of the workflow.</em>','Privacy, human decisions and retained evidence are built into each review.')+`<div class="trust-grid"><section class="panel trust-card"><div class="eyebrow">PRIVATE DATA HANDLING</div><h3>Supplied packs stay on your device.</h3><p>CSV imports, policy text, derived evidence and notes are retained in an IndexedDB vault. Importing or writing a custom policy pauses server synchronization for the entire workspace. No pack is sent to a model or retaining service.</p><p>Generated demo-only workspaces may sync to this private Site. Export a workspace backup before clearing browser data.</p>${secondary('Download workspace backup','backup')}</section><section class="panel trust-card"><div class="eyebrow">HUMAN OVERSIGHT & FAIRNESS</div><h3>Evidence first. No automatic HR changes.</h3><p>Owners submit fix evidence. A separate compliance reviewer verifies closure. Every decision requires a reason; employees can provide clarification, correction or appeal context through the case record.</p><p>Named staff and review contexts are synthetic workflow demonstrations, not application access permissions. Hosted account identity is recorded separately. Enterprise deployment must map real authenticated staff to authorised roles.</p></section><section class="panel trust-card"><div class="eyebrow">POLICY & INVESTIGATION</div><h3>Explicit rules and separate leads.</h3><p>Written English policies compile into supported, reviewable conditions. Unsupported statements remain pending clarification. Human approval activates rules. Statistical investigation leads show their detector and evidence and never claim a policy breach.</p>${primary('Add a written rule','new-rule')}</section><section class="panel trust-card"><div class="eyebrow">SUBMISSION & PILOT</div><h3>Review the complete evidence package.</h3><p>Organiser data was unavailable before submission preparation. This submission uses generated synthetic data and illustrative policies. Template mapping is available when a format is supplied. The solution note documents responsible AI and an internal pilot plan.</p><a class="btn" href="/solution-note.pdf" target="_blank">Solution note · PDF</a></section><section class="panel trust-card"><div class="eyebrow">RETENTION & RECOVERY</div><h3>Portable review history.</h3><p>Every retained batch includes source records, employee register and check-run policy snapshots. Workspace backup includes decisions, source records and audit activity for offline recovery. Keep the backup in an approved synthetic-data location.</p>${secondary('Download full workspace backup','backup')}</section><section class="panel trust-card"><div class="eyebrow">REPEAT PROCESSING</div><h3>Every new batch receives the same scrutiny.</h3><p>Use Batch history to ingest successive synthetic batches and inspect past runs. Playback is a browser demonstration; an enterprise scheduler would call the same processing engine inside the organisation.</p><a class="btn" href="#batches">Open batch history</a></section></div>`;};
const baseAction=action;
action=function(a){if(a==='restore'){restoreWorkspace();return;}if(a==='lead-demo'){generateLeadDemo();return;}if(a==='backup'){download('aeris-private-workspace.json',JSON.stringify(snapshot(),null,2),'application/json');toast('Workspace backup downloaded. Keep it in an approved location.');return;}if(a==='my-queue'){filterOwner=activePerson;render();return;}if(a==='replay'){toggleReplay();return;}if(a==='replay-one'){replayOne();return;}if(a==='leads-export'){download('aeris-investigation-leads.json',JSON.stringify({classification:'Investigation leads only — not policy exceptions',dataset:datasetId,leads:leads()},null,2),'application/json');return;}if(a==='audit-export'){download('aeris-audit-evidence.json',JSON.stringify({prototype:true,storage:protectedData?'device-local private vault':'generated demo private server and device',exported_at:new Date().toISOString(),dataset:datasetId,batch:batchName,rules,findings:findings(),check_outcomes:results.outcomes,batches:batches.map(b=>({id:b.id,name:b.name,source:b.source,counts:b.counts,runs:b.runs})),events:audit},null,2),'application/json');log('Audit evidence exported','Policy snapshots, outcomes, finding evidence and human decisions exported.');toast('Audit evidence exported.');return;}if(persona==='audit'&&['new-rule','rerun','upload','reset'].includes(a)){toast('Switch out of read-only audit context to make changes.');return;}baseAction(a);};
function readCSVHeaders(text){let quoted=false,end=text.length;for(let i=0;i<text.length;i++){if(text[i]==='"'){if(quoted&&text[i+1]==='"')i++;else quoted=!quoted;}else if(!quoted&&(text[i]==='\r'||text[i]==='\n')){end=i;break;}}const header=text.slice(0,end).replace(/^\uFEFF/,'');const row=parseCSV(header+'\n'+header)[0];return row?Object.keys(row):[];}
function generateLeadDemo(){captureBatch();const existing=batches.find(b=>b.id==='anomaly-demo-v1');if(existing){switchBatch(existing.id);return;}const data=generateDemo();transactions=data.transactions.slice(0,1000).map(t=>({...t,transaction_id:'LEAD-'+t.transaction_id}));employees=data.employees;const sample=transactions.find(t=>t.type==='Allowance'&&t.department==='Cabin Operations');if(sample){sample.amount=75000;sample.approver='APR-INDEPENDENT-DEMO';sample.approver_role='HR director';sample.documents='Allowance approval';}datasetId='anomaly-demo-v1';batchName='Unusual-pattern demonstration';batches.push({id:datasetId,name:batchName,source:'generated',createdAt:new Date().toISOString(),runs:[]});log('Investigation demo generated','1,000 synthetic records include a peer-relative allowance outlier; this is an investigation lead, not proof of a policy breach.');runChecks();render();toast('Generated an unusual synthetic example. Review its detector evidence.');}
const baseToggleRule=toggleRule;toggleRule=function(id){if(persona==='audit'){toast('Audit context is read only.');return;}baseToggleRule(id);};
function restoreWorkspace(){drawer('Restore a private workspace backup.',`<p class="subtitle">Restore retained source batches, policy snapshots, decisions and audit history from a previously exported workspace. This operation stays on this device.</p><form id="restoreForm"><div class="form-field"><label for="workspaceBackupFile">Workspace backup · JSON</label><input id="workspaceBackupFile" type="file" accept=".json,application/json" required></div><div class="info-banner">${icon('info')}Restoring replaces this device's active workspace with the backup. Download the current workspace first if you need to keep it. The backup is treated as unverified imported history; it does not establish tamper-proof provenance.</div><label class="check-label"><input type="checkbox" required>I confirm this backup contains only synthetic data, I approve its stored policy configuration, and I want to replace this device's workspace.</label><div id="restoreError"></div><div class="drawer-actions"><button class="btn primary" type="submit">Validate & restore on this device</button><button class="btn" type="button" id="backupBeforeRestore">Download current backup first</button></div></form>`,'LOCAL RECOVERY');$('#backupBeforeRestore').onclick=()=>download('aeris-before-restore.json',JSON.stringify(snapshot(),null,2),'application/json');$('#restoreForm').onsubmit=async e=>{e.preventDefault();try{const file=$('#workspaceBackupFile').files[0];if(file.size>24*1024*1024)throw Error('Backup exceeds the 24 MB prototype limit.');const data=JSON.parse(await file.text());if(data.schemaVersion!==2||!Array.isArray(data.batches)||!data.batches.length||data.batches.length>100)throw Error('This is not a supported Aeris workspace backup.');const ids=new Set();let total=0;for(const b of data.batches){if(!b.id||ids.has(b.id)||!Array.isArray(b.transactions)||!Array.isArray(b.employees)||!Array.isArray(b.rules)||!b.rules.length)throw Error('Invalid or duplicate batch in backup.');ids.add(b.id);validateRows(b.transactions,'transactions');validateRows(b.employees,'employees');b.rules.forEach(validateRule);b.runs=Array.isArray(b.runs)?b.runs:[];total+=b.transactions.length;}if(total>100000)throw Error('Backup contains more than 100,000 transactions.');batches=data.batches;protectedData=true;reviews=data.reviews&&typeof data.reviews==='object'?data.reviews:{};audit=Array.isArray(data.audit)?data.audit:[];pendingEvents=[];exportSchema=data.exportSchema||null;replayIndex=data.replayIndex||0;const b=batches.find(b=>b.id===data.activeBatchId)||batches[0];({transactions,employees,rules}=structuredClone(b));datasetId=b.id;batchName=b.name;lastRun=b.lastRun||new Date().toISOString();lastRunId=b.lastRunId||crypto.randomUUID();results=evaluate(transactions,employees,rules);log('Workspace backup restored',`${batches.length} retained batches restored from a user-supplied backup. History is unverified; all contents remain device-local.`);await vaultWrite(snapshot());storageState='Restored in private device vault; server sync paused';closeDrawer();location.hash='batches';render();toast('Workspace restored on this device. No backup data was uploaded.');}catch(err){$('#restoreError').innerHTML=`<div class="inline-error">${esc(err.message)}</div>`;}};}
async function initialiseWorkspace(){let local;try{local=await vaultRead();}catch{storageState='Device vault unavailable; export backups before leaving';}let remote;try{const response=await fetch('/api/workspace');if(response.ok){remote=await response.json();serverVersion=remote.version||0;session=remote.session||session;}}catch{}const data=local?.protectedData?local:remote?.workspace||local;if(data?.schemaVersion===2&&Array.isArray(data.batches)&&data.batches.length){batches=data.batches;protectedData=!!data.protectedData;reviews=data.reviews||{};audit=data.audit||[];exportSchema=data.exportSchema||null;replayIndex=data.replayIndex||0;const b=batches.find(b=>b.id===data.activeBatchId)||batches[0];({transactions,employees,rules}=structuredClone(b));datasetId=b.id;batchName=b.name;lastRun=b.lastRun||new Date().toISOString();lastRunId=b.lastRunId||crypto.randomUUID();results=evaluate(transactions,employees,rules);storageState=protectedData?'Saved on this device; server sync paused':remote?.workspace?'Saved · private server and device':'Saved in device vault';}else{rules=structuredClone(defaultRules);audit=[];reviews={};runChecks();storageState='Saving generated demo workspace…';}hydrateIcons();navigate();persist();}
$('#main').innerHTML='<div class="empty"><strong>Opening your compliance workspace…</strong>Loading retained batches and policy evidence.</div>';
await initialiseWorkspace();

const bindWithWorkflow=bindMain;bindMain=function(){bindWithWorkflow();for(const [id,update] of [['trendProcess',v=>trendProcess=v],['trendTeam',v=>trendTeam=v],['trendRule',v=>trendRule=v]]){const el=$('#'+id);if(el)el.onchange=()=>{update(el.value);render();};}};
